type chars = char list

(** val str : string -> chars **)

let str =
  (fun s -> List.init (String.length s) (fun i -> s.[i]))

(** val ceq : char -> char -> bool **)

let ceq =
  (=)

(** val ceqs : chars -> chars -> bool **)

let rec ceqs a b =
  match a with
  | [] -> (match b with
           | [] -> true
           | _ :: _ -> false)
  | x :: a' ->
    (match b with
     | [] -> false
     | y :: b' -> (&&) (ceq x y) (ceqs a' b'))

(** val prefix : chars -> chars -> bool **)

let rec prefix p s1 =
  match p with
  | [] -> true
  | x :: p' ->
    (match s1 with
     | [] -> false
     | y :: s' -> (&&) (ceq x y) (prefix p' s'))

(** val suffix : chars -> chars -> bool **)

let suffix p s1 =
  prefix (rev p) (rev s1)

(** val find_from : chars -> chars -> int -> int option **)

let rec find_from p s1 i =
  if prefix p s1
  then Some i
  else (match s1 with
        | [] -> None
        | _ :: s' -> find_from p s' (Stdlib.Int.succ i))

(** val find0 : chars -> chars -> int option **)

let find0 p s1 =
  find_from p s1 0

(** val occurs : chars -> chars -> bool **)

let occurs p s1 =
  match find0 p s1 with
  | Some _ -> true
  | None -> false

(** val count_occ : chars -> chars -> int **)

let rec count_occ p s1 = match s1 with
| [] -> 0
| _ :: s' ->
  add (if prefix p s1 then Stdlib.Int.succ 0 else 0) (count_occ p s')

(** val repl : int -> chars -> chars -> chars -> chars **)

let rec repl fuel from to0 s1 =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> s1)
    (fun f ->
    match s1 with
    | [] -> []
    | c :: s' ->
      if prefix from s1
      then app to0 (repl f from to0 (skipn (length from) s1))
      else c :: (repl f from to0 s'))
    fuel

(** val replace_all : chars -> chars -> chars -> chars **)

let replace_all from to0 s1 =
  repl (Stdlib.Int.succ (length s1)) from to0 s1

