  rev (drop_ws (rev (drop_ws s1)))

(** val blank : chars -> bool **)

let blank s1 =
  forallb is_ws s1

(** val scmp : chars -> chars -> comparison **)

let rec scmp a b =
  match a with
  | [] -> (match b with
           | [] -> Eq
           | _ :: _ -> Lt)
  | x :: a' ->
    (match b with
     | [] -> Gt
     | y :: b' ->
       (match Nat.compare (code x) (code y) with
        | Eq -> scmp a' b'
        | x0 -> x0))

(** val split_on : char -> chars -> chars list **)

let rec split_on sep = function
| [] -> [] :: []
| c :: s' ->
  if ceq c sep
  then [] :: (split_on sep s')
  else (match split_on sep s' with
        | [] -> (c :: []) :: []
        | w :: ws -> (c :: w) :: ws)

(** val concat_with : chars -> chars list -> chars **)

let rec concat_with sep = function
| [] -> []
| w :: l' ->
  (match l' with
   | [] -> w
   | _ :: _ -> app w (app sep (concat_with sep l')))

