(** val ieq : chars -> chars -> bool **)

let ieq a b =
  ceqs (lower a) (lower b)

type 'a r0 =
| Ok0 of 'a
| Uns0 of string

(** val hget : chars -> (chars * val0) list -> val0 **)

let rec hget k = function
| [] -> VNull
| p :: r -> let (k', v) = p in if ieq k k' then v else hget k r

(** val hset : chars -> val0 -> (chars * val0) list -> (chars * val0) list **)

let rec hset k v = function
| [] -> (k, v) :: []
| p :: r ->
  let (k', v') = p in
  if ieq k k' then (k', v) :: r else (k', v') :: (hset k v r)

(** val hremove : chars -> (chars * val0) list -> (chars * val0) list **)

let rec hremove k = function
| [] -> []
| p :: r ->
  let (k', v') = p in
  if ieq k k' then hremove k r else (k', v') :: (hremove k r)

(** val is_meta : char -> bool **)

let is_meta c =
  existsb (fun m -> ceq c m) (str ".[]()+?^$|\\{}")

(** val pmatch : chars -> chars -> bool r0 **)

let pmatch pat name =
  if ieq pat name
  then Ok0 true
  else (match rev pat with
        | [] ->
          if existsb is_meta pat
          then Uns0 "RHS: regex dialect of name patterns not documented"
          else Ok0 false
        | a :: rp ->
          (* If this appears, you're using Ascii internals. Please don't *)
 (fun f c ->
  let n = Char.code c in
  let h i = (n land (1 lsl i)) <> 0 in
  f (h 0) (h 1) (h 2) (h 3) (h 4) (h 5) (h 6) (h 7))
            (fun b b0 b1 b2 b3 b4 b5 b6 ->
            if b
            then if existsb is_meta pat
                 then Uns0
                        "RHS: regex dialect of name patterns not documented"
                 else Ok0 false
            else if b0
                 then if b1
                      then if existsb is_meta pat
                           then Uns0
                                  "RHS: regex dialect of name patterns not documented"
                           else Ok0 false
                      else if b2
                           then if b3
                                then if existsb is_meta pat
                                     then Uns0
                                            "RHS: regex dialect of name patterns not documented"
                                     else Ok0 false
                                else if b4
                                     then if b5
                                          then if existsb is_meta pat
                                               then Uns0
                                                      "RHS: regex dialect of name patterns not documented"
                                               else Ok0 false
                                          else if b6
                                               then if existsb is_meta pat
                                                    then Uns0
                                                           "RHS: regex dialect of name patterns not documented"
                                                    else Ok0 false
                                               else let p = rev rp in
                                                    if prefix (lower p)
                                                         (lower name)
                                                    then Ok0 true
                                                    else if existsb is_meta p
                                                         then Uns0
                                                                "RHS: wildcard pattern that is also a regex"
                                                         else Ok0 false
                                     else if existsb is_meta pat
                                          then Uns0
                                                 "RHS: regex dialect of name patterns not documented"
                                          else Ok0 false
                           else if existsb is_meta pat
                                then Uns0
                                       "RHS: regex dialect of name patterns not documented"
                                else Ok0 false
                 else if existsb is_meta pat
                      then Uns0
                             "RHS: regex dialect of name patterns not documented"
                      else Ok0 false)
            a)

(** val any_match : chars list -> chars -> bool r0 **)

let rec any_match pats name =
  match pats with
  | [] -> Ok0 false
  | p :: r ->
    (match pmatch p name with
     | Ok0 a -> if a then Ok0 true else any_match r name
     | Uns0 w -> Uns0 w)

(** val hremove_pat :
    chars -> chars list -> (chars * val0) list -> (chars * val0) list r0 **)

let rec hremove_pat pat excl = function
| [] -> Ok0 []
| p :: r ->
  let (k, v) = p in
  (match pmatch pat k with
   | Ok0 m ->
     (match any_match excl k with
      | Ok0 x ->
        (match hremove_pat pat excl r with
         | Ok0 r' -> Ok0 (if (&&) m (negb x) then r' else (k, v) :: r')
         | Uns0 w -> Uns0 w)
      | Uns0 w -> Uns0 w)
   | Uns0 w -> Uns0 w)

(** val pset : chars -> val0 -> (chars * val0) list -> (chars * val0) list **)

let rec pset k v = function
| [] -> (k, v) :: []
| p :: r ->
  let (k', v') = p in
  if ceqs k k' then (k', v) :: r else (k', v') :: (pset k v r)

(** val premove : chars -> (chars * val0) list -> (chars * val0) list **)

let rec premove k = function
| [] -> []
| p :: r ->
  let (k', v') = p in
  if ceqs k k' then premove k r else (k', v') :: (premove k r)

(** val pput : chars -> val0 -> (chars * val0) list -> (chars * val0) list **)

let pput k v ps =
  match v with
  | VNull -> premove k ps
  | _ -> pset k v ps

type vscope =
| VExchange
| VGlobal
| VRoute of chars
| VGroup of chars

(** val strip : chars -> chars -> chars option **)

let strip p s1 =
  if prefix p s1 then Some (skipn (length p) s1) else None

(** val split_colon : chars -> (chars * chars) option **)

let rec split_colon = function
| [] -> None
| c :: r ->
  if ceq c ':'
  then Some ([], r)
  else (match split_colon r with
        | Some p -> let (a, b) = p in Some ((c :: a), b)
        | None -> None)

(** val vname : chars -> (vscope * chars) r0 **)

let vname k =
  match strip (str "global:") k with
  | Some r -> Ok0 (VGlobal, r)
  | None ->
    (match strip (str "route:") k with
     | Some r ->
       (match split_colon r with
        | Some p -> let (rid, n0) = p in Ok0 ((VRoute rid), n0)
        | None -> Uns0 "VAR: route: variable name without a route id")
     | None ->
       (match strip (str "group:") k with
        | Some r ->
          (match split_colon r with
           | Some p -> let (g, n0) = p in Ok0 ((VGroup g), n0)
           | None -> Uns0 "VAR: group: variable name without a group")
        | None ->
          (match strip (str "header:") k with
           | Some _ ->
             Uns0
               "VAR: header: variables (received headers) are read-only and set by VariableReceive only [VAR.378-381]"
           | None -> Ok0 (VExchange, k))))

(** val ceqsl : chars list -> chars list -> bool **)

let rec ceqsl a b =
  match a with
  | [] -> (match b with
           | [] -> true
           | _ :: _ -> false)
  | x :: a' ->
    (match b with
     | [] -> false
     | y :: b' -> (&&) (ceqs x y) (ceqsl a' b'))

(** val veqb : val0 -> val0 -> bool **)

let veqb a b =
  match a with
  | VNull -> (match b with
              | VNull -> true
              | _ -> false)
  | VStr x -> (match b with
               | VStr y -> ceqs x y
               | _ -> false)
  | VInt x -> (match b with
               | VInt y -> Z.eqb x y
               | _ -> false)
  | VLong x -> (match b with
                | VLong y -> Z.eqb x y
                | _ -> false)
  | VDbl x -> (match b with
               | VDbl y -> Z.eqb x y
               | _ -> false)
  | VBool x -> (match b with
                | VBool y -> eqb x y
                | _ -> false)
  | VList x -> (match b with
                | VList y -> ceqsl x y
                | _ -> false)

(** val kveqb : (chars * val0) list -> (chars * val0) list -> bool **)

let rec kveqb a b =
  match a with
  | [] -> (match b with
           | [] -> true
           | _ :: _ -> false)
  | p :: a' ->
    let (k, v) = p in
    (match b with
     | [] -> false
     | p0 :: b' ->
       let (k', v') = p0 in (&&) ((&&) (ceqs k k') (veqb v v')) (kveqb a' b'))

type exn =
| MkExnS of chars * chars * exn option * exn list

(** val mkExn : chars -> chars -> exn option -> exn **)

let mkExn c m cause =
  MkExnS (c, m, cause, [])

(** val exn_class : exn -> chars **)

let exn_class = function
| MkExnS (c, _, _, _) -> c

(** val exn_msg : exn -> chars **)

let exn_msg = function
| MkExnS (_, m, _, _) -> m

(** val add_suppressed : exn -> exn -> exn **)

let add_suppressed e s1 =
  let MkExnS (c, m, k, l) = e in MkExnS (c, m, k, (app l (s1 :: [])))

(** val exn_chain : exn -> exn list **)

let rec exn_chain e = match e with
| MkExnS (_, _, cause, _) ->
  (match cause with
   | Some c -> app (exn_chain c) (e :: [])
   | None -> e :: [])

(** val jdk_super : chars -> chars option option **)

let jdk_super c =
  let isc = fun s1 -> ceqs c (str s1) in
  if isc "java.lang.Throwable"
  then Some None
  else if isc "java.lang.Exception"
       then Some (Some (str "java.lang.Throwable"))
       else if isc "java.lang.RuntimeException"
            then Some (Some (str "java.lang.Exception"))
            else if isc "java.io.IOException"
                 then Some (Some (str "java.lang.Exception"))
                 else if isc "java.lang.IllegalArgumentException"
                      then Some (Some (str "java.lang.RuntimeException"))
                      else if isc "java.lang.IllegalStateException"
                           then Some (Some (str "java.lang.RuntimeException"))
                           else if isc "java.lang.NumberFormatException"
                                then Some (Some
                                       (str
                                         "java.lang.IllegalArgumentException"))
                                else if isc
                                          "org.apache.camel.RuntimeCamelException"
                                     then Some (Some
                                            (str "java.lang.RuntimeException"))
                                     else if isc
                                               "org.apache.camel.TypeConversionException"
                                          then Some (Some
                                                 (str
                                                   "org.apache.camel.RuntimeCamelException"))
                                          else if isc
                                                    "org.apache.camel.CamelException"
                                               then Some (Some
                                                      (str
                                                        "java.lang.Exception"))
                                               else if isc
                                                         "org.apache.camel.CamelExchangeException"
                                                    then Some (Some
                                                           (str
                                                             "org.apache.camel.CamelException"))
                                                    else if isc
                                                              "org.apache.camel.processor.aggregate.ClosedCorrelationKeyException"
                                                         then Some (Some
                                                                (str
                                                                  "org.apache.camel.CamelExchangeException"))
                                                         else None

(** val instance_of_f : int -> chars -> chars -> bool r0 **)

let rec instance_of_f fuel c t =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> Uns0 "L0: class hierarchy deeper than the table")
    (fun f ->
    if ceqs c t
    then (match jdk_super t with
          | Some _ -> Ok0 true
          | None -> Uns0 "L0: exception class outside the table")
    else (match jdk_super c with
          | Some o ->
            (match o with
             | Some p -> instance_of_f f p t
             | None ->
               (match jdk_super t with
                | Some _ -> Ok0 false
                | None -> Uns0 "L0: exception class outside the table"))
          | None -> Uns0 "L0: exception class outside the table"))
    fuel

(** val instance_of : chars -> chars -> bool r0 **)

let instance_of c t =
  instance_of_f (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ 0)))))))))) c t

type mep =
| InOnly
| InOut

type message = { m_body : val0; m_headers : (chars * val0) list }

type exchange = { x_msg : message; x_props : (chars * val0) list;
                  x_vars : (chars * val0) list; x_mep : mep;
                  x_exn : exn option; x_stop : bool; x_eh : bool;
                  x_seen : bool; x_done : bool; x_uow : (chars * chars) list;
                  x_orig : message option }

type agroup = { ag_x : exchange; ag_n : int; ag_in : exchange list }

type gstate = { g_global : (chars * val0) list;
                g_route : (chars * (chars * val0) list) list;
                g_group : (chars * (chars * val0) list) list;
                g_agg : (chars * (chars * agroup) list) list;
                g_closed : (chars * chars list) list;
                g_cnt : (chars * int) list }

(** val g0 : gstate **)

let g0 =
  { g_global = []; g_route = []; g_group = []; g_agg = []; g_closed = [];
    g_cnt = [] }

(** val new_exchange : mep -> val0 -> (chars * val0) list -> exchange **)

let new_exchange m body hs =
  { x_msg = { m_body = body; m_headers = hs }; x_props = []; x_vars = [];
    x_mep = m; x_exn = None; x_stop = false; x_eh = true; x_seen = false;
    x_done = false; x_uow = []; x_orig = (Some { m_body = body; m_headers =
    hs }) }

(** val with_msg : exchange -> message -> exchange **)

let with_msg x m =
  { x_msg = m; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen = x.x_seen;
    x_done = x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_body : exchange -> val0 -> exchange **)

let set_body x v =
  with_msg x { m_body = v; m_headers = x.x_msg.m_headers }

(** val map_headers :
    ((chars * val0) list -> (chars * val0) list) -> exchange -> exchange **)

let map_headers f x =
  with_msg x { m_body = x.x_msg.m_body; m_headers = (f x.x_msg.m_headers) }

(** val map_props :
    ((chars * val0) list -> (chars * val0) list) -> exchange -> exchange **)

let map_props f x =
  { x_msg = x.x_msg; x_props = (f x.x_props); x_vars = x.x_vars; x_mep =
    x.x_mep; x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen =
    x.x_seen; x_done = x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val map_vars :
    ((chars * val0) list -> (chars * val0) list) -> exchange -> exchange **)

let map_vars f x =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = (f x.x_vars); x_mep =
    x.x_mep; x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen =
    x.x_seen; x_done = x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_exn : exchange -> exn option -> exchange **)

let set_exn x e =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = e; x_stop = x.x_stop; x_eh = x.x_eh; x_seen = false; x_done =
    x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_stop : exchange -> bool -> exchange **)

let set_stop x b =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = b; x_eh = x.x_eh; x_seen = x.x_seen; x_done =
    x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_eh : exchange -> bool -> exchange **)

let set_eh x b =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = x.x_stop; x_eh = b; x_seen = x.x_seen; x_done =
    x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_seen : exchange -> bool -> exchange **)

let set_seen x b =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen = b; x_done =
    x.x_done; x_uow = x.x_uow; x_orig = x.x_orig }

(** val set_done : exchange -> bool -> exchange **)

let set_done x b =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen = x.x_seen;
    x_done = b; x_uow = x.x_uow; x_orig = x.x_orig }

(** val aget :
    chars -> (chars * (chars * val0) list) list -> (chars * val0) list **)

let rec aget k = function
| [] -> []
| p :: r -> let (k', v) = p in if ceqs k k' then v else aget k r

(** val aset :
    chars -> (chars * val0) list -> (chars * (chars * val0) list) list ->
    (chars * (chars * val0) list) list **)

let rec aset k v = function
| [] -> (k, v) :: []
| p :: r ->
  let (k', v') = p in
  if ceqs k k' then (k', v) :: r else (k', v') :: (aset k v r)

(** val var_set :
    exchange -> gstate -> chars -> val0 -> (exchange * gstate) r0 **)

let var_set x g k v =
  match vname k with
  | Ok0 a ->
    let (v0, n0) = a in
    (match v0 with
     | VExchange -> Ok0 ((map_vars (pput n0 v) x), g)
     | VGlobal ->
       Ok0 (x, { g_global = (pput n0 v g.g_global); g_route = g.g_route;
         g_group = g.g_group; g_agg = g.g_agg; g_closed = g.g_closed; g_cnt =
         g.g_cnt })
     | VRoute rid ->
       Ok0 (x, { g_global = g.g_global; g_route =
         (aset rid (pput n0 v (aget rid g.g_route)) g.g_route); g_group =
         g.g_group; g_agg = g.g_agg; g_closed = g.g_closed; g_cnt = g.g_cnt })
     | VGroup gr ->
       Ok0 (x, { g_global = g.g_global; g_route = g.g_route; g_group =
         (aset gr (pput n0 v (aget gr g.g_group)) g.g_group); g_agg = g.g_agg;
         g_closed = g.g_closed; g_cnt = g.g_cnt }))
  | Uns0 w -> Uns0 w

(** val var_remove : exchange -> gstate -> chars -> (exchange * gstate) r0 **)

let var_remove x g k =
  if ceqs k (str "*")
  then Ok0 ((map_vars (fun _ -> []) x), g)
  else if existsb (fun c -> ceq c '*') k
       then Uns0 "RVAR: wildcard variable names other than * not documented"
       else (match vname k with
             | Ok0 a ->
               let (v, n0) = a in
               (match v with
                | VExchange -> Ok0 ((map_vars (premove n0) x), g)
                | VGlobal ->
                  Ok0 (x, { g_global = (premove n0 g.g_global); g_route =
                    g.g_route; g_group = g.g_group; g_agg = g.g_agg;
                    g_closed = g.g_closed; g_cnt = g.g_cnt })
                | VRoute rid ->
                  Ok0 (x, { g_global = g.g_global; g_route =
                    (aset rid (premove n0 (aget rid g.g_route)) g.g_route);
                    g_group = g.g_group; g_agg = g.g_agg; g_closed =
                    g.g_closed; g_cnt = g.g_cnt })
                | VGroup gr ->
                  Ok0 (x, { g_global = g.g_global; g_route = g.g_route;
                    g_group =
                    (aset gr (premove n0 (aget gr g.g_group)) g.g_group);
                    g_agg = g.g_agg; g_closed = g.g_closed; g_cnt = g.g_cnt }))
             | Uns0 w -> Uns0 w)

type jtype =
| TString
| TInteger
| TLong
| TDouble
| TBoolean
| TPInt
| TPLong
| TPDouble
| TPBoolean
| TNumber
| TBigDecimal
| TList
| TObject

(** val jname : jtype -> string **)

let jname = function
| TString -> "java.lang.String"
| TInteger -> "java.lang.Integer"
| TLong -> "java.lang.Long"
| TDouble -> "java.lang.Double"
| TBoolean -> "java.lang.Boolean"
| TPInt -> "int"
| TPLong -> "long"
| TPDouble -> "double"
| TPBoolean -> "boolean"
| TNumber -> "java.lang.Number"
| TBigDecimal -> "java.math.BigDecimal"
| TList -> "java.util.List"
| TObject -> "java.lang.Object"

(** val is_prim : jtype -> bool **)

let is_prim = function
| TPInt -> true
| TPLong -> true
| TPDouble -> true
| TPBoolean -> true
| _ -> false

