(** val canon_int : chars -> Big_int_Z.big_int option **)

let canon_int s1 =
  match parse_dec s1 with
  | Some d ->
    let (z0, n0) = d in
    ((fun fO fS n -> if n=0 then fO () else fS (n-1))
       (fun _ -> if ceqs (ztext z0) s1 then Some z0 else None)
       (fun _ -> None)
       n0)
  | None -> None

