type conv =
| KV of val0
| KDec of dec
| KNull
| KCannot of string
| KUns of string

(** val prim_zero : jtype -> val0 **)

let prim_zero = function
| TPInt -> VInt Big_int_Z.zero_big_int
| TPLong -> VLong Big_int_Z.zero_big_int
| TPDouble -> VDbl Big_int_Z.zero_big_int
| _ -> VBool false

(** val conv_null : jtype -> conv **)

let conv_null t =
  if is_prim t then KV (prim_zero t) else KNull

(** val conv_string : val0 -> conv **)

let conv_string = function
| VNull -> KNull
| VStr s1 -> KV (VStr s1)
| VInt z0 -> KV (VStr (ztext z0))
| VLong z0 -> KV (VStr (ztext z0))
| VDbl _ -> KUns "TC: String from a Double (its text is not documented)"
| VBool b -> KV (VStr (btext b))
| VList _ -> KUns "TC: String from a List (its text is not documented)"

(** val conv_integral :
    string -> (Big_int_Z.big_int -> val0) -> (Big_int_Z.big_int -> bool) ->
    val0 -> conv **)

let conv_integral nm0 mk lim = function
| VNull -> KNull
| VStr s1 ->
  (match canon_int s1 with
   | Some z0 ->
     if lim z0
     then KV (mk z0)
     else KUns ((^) "TC: " ((^) nm0 " from integer text out of its range"))
   | None ->
     if wordy s1
     then KCannot "a word is not a number"
     else KUns ((^) "TC: " ((^) nm0 ((^) " from " (text_kind s1)))))
| VInt z0 ->
  if lim z0
  then KV (mk z0)
  else KUns ((^) "TC: " ((^) nm0 " from a number out of its range"))
| VLong z0 ->
  if lim z0
  then KV (mk z0)
  else KUns ((^) "TC: " ((^) nm0 " from a number out of its range"))
| VDbl q ->
  if (&&)
       (Z.eqb
         (Z.modulo q ((fun p -> Big_int_Z.shift_left_big_int p 1)
           ((fun p -> Big_int_Z.shift_left_big_int p 1)
           Big_int_Z.unit_big_int)))
         Big_int_Z.zero_big_int)
       (lim
         (Z.div q ((fun p -> Big_int_Z.shift_left_big_int p 1)
           ((fun p -> Big_int_Z.shift_left_big_int p 1)
           Big_int_Z.unit_big_int))))
  then KV
         (mk
           (Z.div q ((fun p -> Big_int_Z.shift_left_big_int p 1)
             ((fun p -> Big_int_Z.shift_left_big_int p 1)
             Big_int_Z.unit_big_int))))
  else KUns
         ((^) "TC: "
           ((^) nm0 " from a Double with a fraction or out of range"))
| VBool _ -> KUns ((^) "TC: " ((^) nm0 " from a Boolean"))
| VList _ -> KUns ((^) "TC: " ((^) nm0 " from a List"))

(** val conv_double : val0 -> conv **)

let conv_double = function
| VNull -> KNull
| VStr s1 ->
  (match plain_dec s1 with
   | Some d ->
     (match dec_quarters d with
      | Some q ->
        if in_dbl_exact q
        then KV (VDbl q)
        else KUns
               "TC: Double from a decimal text that a Double does not hold exactly"
      | None ->
        KUns
          "MODEL: Double from a decimal text that is not a whole number of quarters")
   | None ->
     if wordy s1
     then KCannot "a word is not a number"
     else KUns ((^) "TC: Double from " (text_kind s1)))
| VInt z0 ->
  if in_dbl_exact z0
  then KV (VDbl
         (Z.mul ((fun p -> Big_int_Z.shift_left_big_int p 1)
           ((fun p -> Big_int_Z.shift_left_big_int p 1)
           Big_int_Z.unit_big_int)) z0))
  else KUns "TC: Double from a long beyond 2^53"
| VLong z0 ->
  if in_dbl_exact z0
  then KV (VDbl
         (Z.mul ((fun p -> Big_int_Z.shift_left_big_int p 1)
           ((fun p -> Big_int_Z.shift_left_big_int p 1)
           Big_int_Z.unit_big_int)) z0))
  else KUns "TC: Double from a long beyond 2^53"
| VDbl q -> KV (VDbl q)
| VBool _ -> KUns "TC: Double from a Boolean"
| VList _ -> KUns "TC: Double from a List"

(** val conv_bool : val0 -> conv **)

let conv_bool = function
| VNull -> KNull
| VStr s1 ->
  if ceqs s1 (str "true")
  then KV (VBool true)
  else if ceqs s1 (str "false")
       then KV (VBool false)
       else KUns "TC: Boolean from text other than true/false"
| VBool b -> KV (VBool b)
| VList _ -> KUns "TC: Boolean from a List"
| _ -> KUns "TC: Boolean from a number"

(** val number_int_text : Big_int_Z.big_int -> conv **)

let number_int_text z0 =
  KV (VInt z0)

(** val number_exp_text : Big_int_Z.big_int -> conv **)

let number_exp_text z0 =
  if in_dbl_exact z0
  then KV (VDbl
         (Z.mul ((fun p -> Big_int_Z.shift_left_big_int p 1)
           ((fun p -> Big_int_Z.shift_left_big_int p 1)
           Big_int_Z.unit_big_int)) z0))
  else KUns "UG423: Number from exponent text beyond 2^53"

(** val number_other_text : chars -> conv **)

let number_other_text s1 =
  match canon_int s1 with
  | Some z0 ->
    if in_long z0
    then KV (VLong z0)
    else KUns "UG423: Number from integer text beyond the Long range"
  | None ->
    (match plain_dec s1 with
     | Some d ->
       (match dec_quarters d with
        | Some q ->
          if in_dbl_exact q
          then KV (VDbl q)
          else KUns
                 "UG423: Number from a decimal text that a Double does not hold exactly"
        | None ->
          KUns
            "MODEL: Number from a decimal text that is not a whole number of quarters")
     | None -> KUns ((^) "UG423: Number from " (text_kind s1)))

(** val conv_number : val0 -> conv **)

let conv_number = function
| VNull -> KNull
| VStr s1 ->
  (match canon_int s1 with
   | Some z0 -> if in_int z0 then number_int_text z0 else number_other_text s1
   | None ->
     (match exp_int s1 with
      | Some z0 -> number_exp_text z0
      | None ->
        if wordy s1
        then KCannot "a word is not a number"
        else number_other_text s1))
| VBool _ -> KUns "TC: Number from a Boolean"
| VList _ -> KUns "TC: Number from a List"
| x -> KV x

(** val conv_bigdec : val0 -> conv **)

let conv_bigdec = function
| VNull -> KNull
| VStr s1 ->
  (match plain_dec s1 with
   | Some d -> KDec d
   | None ->
     if wordy s1
     then KCannot "a word is not a number"
     else KUns ((^) "UG423: BigDecimal from " (text_kind s1)))
| VInt z0 -> KDec (z0, 0)
| VLong z0 -> KDec (z0, 0)
| VDbl q ->
  KDec
    ((Z.mul q
       ((fun p -> Big_int_Z.succ_big_int (Big_int_Z.shift_left_big_int p 1))
       ((fun p -> Big_int_Z.shift_left_big_int p 1)
       ((fun p -> Big_int_Z.shift_left_big_int p 1)
       ((fun p -> Big_int_Z.succ_big_int (Big_int_Z.shift_left_big_int p 1))
       Big_int_Z.unit_big_int))))),
    (Stdlib.Int.succ (Stdlib.Int.succ 0)))
| VBool _ -> KUns "UG423: BigDecimal from a Boolean"
| VList _ -> KUns "UG423: BigDecimal from a List"

(** val conv_list : val0 -> conv **)

let conv_list = function
| VNull -> KNull
| VList l -> KV (VList l)
| _ -> KUns "TC: List from a value that is not a List"

(** val conv_of : val0 -> jtype -> conv **)

let conv_of v t =
  match v with
  | VNull -> conv_null t
  | _ ->
    (match t with
     | TString -> conv_string v
     | TInteger -> conv_integral "Integer" (fun x -> VInt x) in_int v
     | TLong -> conv_integral "Long" (fun x -> VLong x) in_long v
     | TDouble -> conv_double v
     | TPInt -> conv_integral "Integer" (fun x -> VInt x) in_int v
     | TPLong -> conv_integral "Long" (fun x -> VLong x) in_long v
     | TPDouble -> conv_double v
     | TNumber -> conv_number v
     | TBigDecimal -> conv_bigdec v
     | TList -> conv_list v
     | TObject -> KV v
     | _ -> conv_bool v)

type exch = { ex_body : val0; ex_headers : (chars * val0) list;
              ex_props : (chars * val0) list; ex_vars : (chars * val0) list }

(** val lookup : chars -> (chars * val0) list -> val0 **)

let rec lookup k = function
| [] -> VNull
| p :: l' -> let (k', v) = p in if ceqs k k' then v else lookup k l'

(** val with_body : exch -> val0 -> exch **)

let with_body x v =
  { ex_body = v; ex_headers = x.ex_headers; ex_props = x.ex_props; ex_vars =
    x.ex_vars }

type res =
| RV of val0
| RLoose of chars
| RErr
| RUns of string

(** val bind : res -> (val0 -> res) -> res **)

let bind r k =
  match r with
  | RV v -> k v
  | RLoose _ -> RUns "loose value used"
  | x -> x

(** val bind_text : res -> (chars -> res) -> res **)

let bind_text r k =
  match r with
  | RV v ->
    (match text_of v with
     | Some s1 -> k s1
     | None -> RUns "text of null or list")
  | RLoose s1 -> k s1
  | x -> x

type lit =
| LQ of chars
| LNum of Big_int_Z.big_int
| LNull
| LTrue
| LFalse
| LBare of chars

type binop =
| OEq
| ONe
| OEqIc
| ONeIc
| OGt
| OGe
| OLt
| OLe
| OCIc
| ONCIc
| OContains
| ONContains
| OEnds
| ONEnds
| OEquals
| ONEquals
| OIn
| ONIn
| OIs
| ONIs
| ORange
| ONRange
| ORegex
| ONRegex
| OStarts
| ONStarts

(** val opstr : binop -> chars **)

let opstr o =
  str
    (match o with
     | OEq -> "=="
     | ONe -> "!="
     | OEqIc -> "=~"
     | ONeIc -> "!=~"
     | OGt -> ">"
     | OGe -> ">="
     | OLt -> "<"
     | OLe -> "<="
     | OCIc -> "~~"
     | ONCIc -> "!~~"
     | OContains -> "contains"
     | ONContains -> "!contains"
     | OEnds -> "endsWith"
     | ONEnds -> "!endsWith"
     | OEquals -> "equals"
     | ONEquals -> "!equals"
     | OIn -> "in"
     | ONIn -> "!in"
     | OIs -> "is"
     | ONIs -> "!is"
     | ORange -> "range"
     | ONRange -> "!range"
     | ORegex -> "regex"
     | ONRegex -> "!regex"
     | OStarts -> "startsWith"
     | ONStarts -> "!startsWith")

type lop =
| LAnd
| LOr

type fn =
| FBody
| FHeader of int * chars
| FProp of int * chars
| FVar of chars
| FNull
| FHeadersSize
| FTyped of int * fn
| FCall of chars * bool * args
| FPred of pseq
| FTern of pseq * tval * tval
and args =
| ANil
| ACons of arg * args
and arg =
| AFn of fn
| ALit of lit
| APred of pseq
and tval =
| TVLit of lit
| TVFn of fn
and atom =
| ACmp of lhs * binop * rhs
| ANot of fn
| AFun of fn
| ANot2 of fn
and lhs =
| LFn of fn
| LInc of fn
| LDecr of fn
| LNotFn of fn
and rhs =
| RLit of lit
| RFn of fn
| RNot of fn
and pseq =
| PS of atom * prest
and prest =
| PNil
| PCons of lop * atom * prest

type part =
| TText of chars
| TFn of bool * fn
| TPost of fn * bool

type prog =
| PExpr of part list
| PPred of pseq
| PElvis of fn * lit
| PChain of bool * fn * fn list

(** val dq : chars **)

let dq =
  str "${"

(** val rlit : lit -> chars **)

let rlit = function
| LQ s1 -> '\'' :: (app s1 ('\'' :: []))
| LNum z0 -> ztext z0
| LNull -> str "null"
| LTrue -> str "true"
| LFalse -> str "false"
| LBare s1 -> s1

(** val typed_prefix : int -> chars **)

let typed_prefix t =
  str
    ((fun fO fS n -> if n=0 then fO () else fS (n-1))
       (fun _ -> "int:")
       (fun n0 ->
       (fun fO fS n -> if n=0 then fO () else fS (n-1))
         (fun _ -> "integer:")
         (fun n1 ->
         (fun fO fS n -> if n=0 then fO () else fS (n-1))
           (fun _ -> "long:")
           (fun n2 ->
           (fun fO fS n -> if n=0 then fO () else fS (n-1))
             (fun _ -> "boolean:")
             (fun _ -> "string:")
             n2)
           n1)
         n0)
       t)

(** val rfn : fn -> chars **)

let rec rfn = function
| FBody -> str "body"
| FHeader (sty, k) ->
  ((fun fO fS n -> if n=0 then fO () else fS (n-1))
     (fun _ -> app (str "header.") k)
     (fun n0 ->
     (fun fO fS n -> if n=0 then fO () else fS (n-1))
       (fun _ -> app (str "header[") (app k (str "]")))
       (fun n1 ->
       (fun fO fS n -> if n=0 then fO () else fS (n-1))
         (fun _ -> app (str "headers.") k)
         (fun n2 ->
         (fun fO fS n -> if n=0 then fO () else fS (n-1))
           (fun _ -> app (str "headers:") k)
           (fun _ -> app (str "headers[") (app k (str "]")))
           n2)
         n1)
       n0)
     sty)
| FProp (sty, k) ->
  ((fun fO fS n -> if n=0 then fO () else fS (n-1))
     (fun _ -> app (str "exchangeProperty.") k)
     (fun n0 ->
     (fun fO fS n -> if n=0 then fO () else fS (n-1))
       (fun _ -> app (str "exchangeProperty:") k)
       (fun _ -> app (str "exchangeProperty[") (app k (str "]")))
       n0)
     sty)
| FVar k -> app (str "variable.") k
| FNull -> str "null"
| FHeadersSize -> str "headers.size"
| FTyped (t, g) -> app (typed_prefix t) (rfn g)
| FCall (n0, sp, a) -> app n0 ('(' :: (app (rargs sp a) (')' :: [])))
| FPred p -> rps true p
| FTern (c, t, e) ->
  app (rps true c) (app (str " ? ") (app (rtv t) (app (str " : ") (rtv e))))

(** val rargs : bool -> args -> chars **)

and rargs sp = function
| ANil -> []
| ACons (x, r) ->
  (match r with
   | ANil -> rarg x
   | ACons (_, _) ->
     app (rarg x) (app (if sp then str ", " else str ",") (rargs sp r)))

(** val rarg : arg -> chars **)

and rarg = function
| AFn f -> app dq (app (rfn f) (str "}"))
| ALit l -> rlit l
| APred p -> rps false p

(** val rtv : tval -> chars **)

and rtv = function
| TVLit l -> rlit l
| TVFn f -> app dq (app (rfn f) (str "}"))

(** val ratom : bool -> atom -> chars **)

and ratom inb = function
| ACmp (l, o, r) ->
  app (rlhs inb l) (' ' :: (app (opstr o) (' ' :: (rrhs r))))
| ANot f ->
  if inb then '!' :: (rfn f) else app (str "!${") (app (rfn f) (str "}"))
| AFun f -> if inb then rfn f else app dq (app (rfn f) (str "}"))
| ANot2 f ->
  if inb
  then app (str "!!") (rfn f)
  else app (str "!!${") (app (rfn f) (str "}"))

(** val rlhs : bool -> lhs -> chars **)

and rlhs inb = function
| LFn f -> if inb then rfn f else app dq (app (rfn f) (str "}"))
| LInc f ->
  app (if inb then rfn f else app dq (app (rfn f) (str "}"))) (str "++")
| LDecr f ->
  app (if inb then rfn f else app dq (app (rfn f) (str "}"))) (str "--")
| LNotFn f ->
  if inb then '!' :: (rfn f) else app (str "!${") (app (rfn f) (str "}"))

(** val rrhs : rhs -> chars **)

and rrhs = function
| RLit l -> rlit l
| RFn f -> app dq (app (rfn f) (str "}"))
| RNot f -> app (str "!${") (app (rfn f) (str "}"))

(** val rps : bool -> pseq -> chars **)

and rps inb = function
| PS (a, r) -> app (ratom inb a) (rprest inb r)

(** val rprest : bool -> prest -> chars **)

and rprest inb = function
| PNil -> []
| PCons (o, a, r') ->
  app (match o with
       | LAnd -> str " && "
       | LOr -> str " || ")
    (app (ratom inb a) (rprest inb r'))

(** val rpart : part -> chars **)

let rpart = function
| TText s1 -> s1
| TFn (alt, f) ->
  app (if alt then str "$simple{" else dq) (app (rfn f) (str "}"))
| TPost (f, inc) ->
  app dq (app (rfn f) (app (str "}") (if inc then str "++" else str "--")))

(** val render : prog -> chars **)

let render = function
| PExpr t -> concat (map rpart t)
| PPred q -> rps false q
| PElvis (f, d) -> app dq (app (rfn f) (app (str "} ?: ") (rlit d)))
| PChain (ns, f, fs) ->
  app dq
    (app (rfn f)
      (app (str "}")
        (concat
          (map (fun g ->
            app (if ns then str " ?~> " else str " ~> ")
              (app dq (app (rfn g) (str "}"))))
            fs))))

(** val is_predicate : prog -> bool **)

let is_predicate = function
| PPred _ -> true
| _ -> false

