(** val q_value : bool -> chars -> res **)

let q_value infn s1 =
  if existsb (fun c -> ceq c '\'') s1
  then RUns "quote inside a quoted literal"
  else if (&&) (negb infn) (occurs ('\\' :: []) s1)
       then RUns
              "MINOR: escape in a quoted operand outside ${ } is not processed"
       else (match unesc infn s1 with
             | Some v -> RV (VStr v)
             | None -> RUns "escape, $ or brace in a literal")

