(** val capitalize : chars -> res **)

let capitalize s1 =
  let ws = split_on ' ' s1 in
  if existsb (fun w ->
       match w with
       | [] -> true
       | _ :: _ -> negb (forallb is_lower w)) ws
  then RUns "capitalize: not lower-case words"
  else RV (VStr
         (concat_with (' ' :: [])
           (map (fun w -> match w with
                          | [] -> []
                          | c :: r -> (upc c) :: r) ws)))

(** val normalize_ws : chars -> res **)

let normalize_ws s1 =
  if existsb (fun c -> (&&) (is_ws c) (negb (ceq c ' '))) s1
  then RUns "normalizeWhitespace: tab or line break"
  else RV (VStr
         (concat_with (' ' :: [])
           (filter (fun w -> match w with
                             | [] -> false
                             | _ :: _ -> true)
             (split_on ' ' s1))))

