    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    0))))))))))))))))))))))))))))))))))

(** val quote_f : chars -> res **)

let quote_f s1 = match s1 with
| [] -> RV (VStr (dquote :: (dquote :: [])))
| c :: r ->
  if (&&) (ceq c '\'') (suffix ('\'' :: []) r)
  then RV (VStr (dquote :: (app (removelast r) (dquote :: []))))
  else if (||) (ceq c dquote) (suffix (dquote :: []) s1)
       then RUns "quote: already double quoted"
       else RV (VStr (dquote :: (app s1 (dquote :: []))))

(** val unquote_f : chars -> res **)

let unquote_f s1 = match s1 with
| [] -> RV (VStr [])
| c :: r ->
  (match r with
   | [] ->
     if (||) (ceq c '\'') (ceq c dquote)
     then RUns "unquote: lone quote"
     else RV (VStr s1)
   | _ :: _ ->
     if (||) ((&&) (ceq c '\'') (suffix ('\'' :: []) r))
          ((&&) (ceq c dquote) (suffix (dquote :: []) r))
     then RV (VStr (removelast r))
     else if (||)
               ((||) ((||) (ceq c '\'') (ceq c dquote))
                 (suffix ('\'' :: []) s1))
               (suffix (dquote :: []) s1)
          then RUns "unquote: one-sided"
          else RV (VStr s1))

(** val substring1 : Big_int_Z.big_int -> chars -> res **)

let substring1 n0 s1 =
  let len = Z.of_nat (length s1) in
  if Z.leb Big_int_Z.zero_big_int n0
  then if Z.leb len n0
       then RV (VStr [])
       else RV (VStr (skipn (Z.to_nat n0) s1))
  else if Z.leb (Z.opp n0) len
       then RV (VStr (firstn (Z.to_nat (Z.add len n0)) s1))
       else RUns "substring: negative clip longer than the text"

(** val substring2 :
    Big_int_Z.big_int -> Big_int_Z.big_int -> chars -> res **)

let substring2 n1 n2 s1 =
  let len = Z.of_nat (length s1) in
  if Z.ltb n1 Big_int_Z.zero_big_int
  then RUns "substring: negative first number"
  else if Z.ltb len (Z.add n1 (Z.abs n2))
       then RUns "substring: clips exceed the text"
       else RV (VStr
              (firstn (Z.to_nat (Z.sub (Z.sub len n1) (Z.abs n2)))
                (skipn (Z.to_nat n1) s1)))

(** val sub_before : chars -> chars -> res **)

let sub_before b s1 =
  match b with
  | [] -> RUns "empty marker"
  | _ :: _ ->
    if negb ((=) (count_occ b s1) (Stdlib.Int.succ 0))
    then RUns "marker not exactly once"
    else (match find0 b s1 with
          | Some i ->
            ((fun fO fS n -> if n=0 then fO () else fS (n-1))
               (fun _ -> RUns
               "DOC: nothing before: empty text, not null")
               (fun _ -> RV (VStr (firstn i s1)))
               i)
          | None -> RUns "not found")

(** val sub_after : chars -> chars -> res **)

let sub_after a s1 =
  match a with
  | [] -> RUns "empty marker"
  | _ :: _ ->
    if negb ((=) (count_occ a s1) (Stdlib.Int.succ 0))
    then RUns "marker not exactly once"
    else (match find0 a s1 with
          | Some i ->
            (match skipn (add i (length a)) s1 with
             | [] -> RUns "DOC: nothing after: empty text, not null"
             | a0 :: l -> RV (VStr (a0 :: l)))
          | None -> RUns "not found")

(** val sub_between : chars -> chars -> chars -> res **)

let sub_between a b s1 =
  match a with
  | [] -> RUns "empty marker"
  | _ :: _ ->
    (match b with
     | [] -> RUns "empty marker"
     | _ :: _ ->
       if negb ((=) (count_occ a s1) (Stdlib.Int.succ 0))
       then RUns "marker not exactly once"
       else (match find0 a s1 with
             | Some i ->
               let r = skipn (add i (length a)) s1 in
               if negb ((=) (count_occ b r) (Stdlib.Int.succ 0))
               then RUns "second marker not exactly once after the first"
               else (match find0 b r with
                     | Some j ->
                       ((fun fO fS n -> if n=0 then fO () else fS (n-1))
                          (fun _ -> RUns
                          "DOC: nothing between: empty text, not null")
                          (fun _ -> RV (VStr (firstn j r)))
                          j)
                     | None -> RUns "not found")
             | None -> RUns "not found"))

(** val pad_f : chars -> Big_int_Z.big_int -> chars -> res **)

let pad_f s1 w = function
| [] -> RUns "pad: separator of several characters"
| c :: l ->
  (match l with
   | [] ->
     let need = sub (Z.to_nat (Z.abs w)) (length s1) in
     if Z.leb Big_int_Z.zero_big_int w
     then RV (VStr (app s1 (repeat_c c need)))
     else RV (VStr (app (repeat_c c need) s1))
   | _ :: _ -> RUns "pad: separator of several characters")

