(** val is_unreserved : char -> bool **)

let is_unreserved c =
  (||)
    ((||)
      ((||) ((||) ((||) (is_letter c) (is_digit c)) (ceq c '-')) (ceq c '.'))
      (ceq c '_'))
    (ceq c '~')

(** val is_reserved : char -> bool **)

let is_reserved c =
  existsb (fun d -> ceq c d) (str ":/?#[]@!$&'()*+,;=")

(** val esc_map : (char -> chars option) -> chars -> chars option **)

let rec esc_map f = function
| [] -> Some []
| c :: s' ->
  (match f c with
   | Some a ->
     (match esc_map f s' with
      | Some b -> Some (app a b)
      | None -> None)
   | None -> None)

