(** val esc_sql : char -> chars option **)

let esc_sql c =
  if ceq c '\'' then Some (str "''") else Some (c :: [])

(** val esc_json : char -> chars option **)

let esc_json c =
  if Nat.ltb (code c) (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
       (Stdlib.Int.succ 0))))))))))))))))))))))))))))))))
  then None
  else if ceq c dquote
       then Some ('\\' :: (dquote :: []))
       else if ceq c '\\' then Some (str "\\\\") else Some (c :: [])

(** val esc_url : char -> chars option **)

let esc_url c =
  if is_unreserved c
  then Some (c :: [])
  else if ceq c ' '
       then Some (str "%20")
       else if is_reserved c
            then None
            else Some
                   ('%' :: ((hexd
                              (Nat.div (code c) (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ (Stdlib.Int.succ
                                (Stdlib.Int.succ 0)))))))))))))))))) :: (
                   (hexd
                     (Nat.modulo (code c) (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ (Stdlib.Int.succ 0)))))))))))))))))) :: [])))

(** val escape_f : chars -> chars -> res **)

let escape_f kind s1 =
  let k = lower kind in
  let go = fun f ->
    match esc_map f s1 with
    | Some r -> RV (VStr r)
    | None -> RUns "escape: form not documented"
  in
  if ceqs k (str "xml")
  then go esc_xml
  else if ceqs k (str "html")
       then go esc_html
       else if ceqs k (str "sql")
            then go esc_sql
            else if ceqs k (str "json")
                 then go esc_json
                 else if ceqs k (str "url")
                      then go esc_url
                      else RUns "escape: other kind"

(** val all_of : (char -> bool) -> chars -> res **)

let all_of p s1 = match s1 with
| [] -> RUns "is*: empty text"
| _ :: _ -> RV (VBool (forallb p s1))

type bres =
| BV of bool
| BErr
| BUns of string

(** val truth : val0 -> bres **)

let truth = function
| VNull -> BV false
| VStr s1 ->
  if (||) (ceqs (lower s1) (str "true")) (ceqs (lower s1) (str "false"))
  then BUns "truth of the text true/false"
  else if blank s1
       then BUns "DOC: truth of an empty or blank text"
       else BV true
| VBool b -> BV b
| VList l ->
  (match l with
   | [] -> BUns "DOC: truth of an empty list"
   | _ :: _ -> BV true)
| _ -> BV true

(** val elvis_truth : val0 -> bres **)

let elvis_truth = function
| VNull -> BV false
| VStr s1 ->
  if blank s1
  then BV false
  else if (||) ((||) (ceqs s1 (str "0")) (ceqs s1 (str "false")))
            (ceqs s1 (str "true"))
       then BUns "elvis truth of 0/true/false text"
       else BV true
| VInt z0 -> BV (negb (Z.eqb z0 Big_int_Z.zero_big_int))
| VLong z0 -> BV (negb (Z.eqb z0 Big_int_Z.zero_big_int))
| VDbl q -> BV (negb (Z.eqb q Big_int_Z.zero_big_int))
| VBool b -> BV b
| VList _ -> BUns "elvis truth of a list"

(** val to_bool : val0 -> bool option option **)

let to_bool = function
| VStr s1 ->
  if ceqs s1 (str "true")
  then Some (Some true)
  else if ceqs s1 (str "false") then Some (Some false) else None
| VBool b -> Some (Some b)
| _ -> Some None

(** val eqv : val0 -> val0 -> bool option **)

let eqv l r =
  match l with
  | VNull -> (match r with
              | VNull -> Some true
              | _ -> Some false)
  | VStr s1 ->
    (match r with
     | VNull -> Some false
     | VStr t ->
       if (&&) (all_digits s1) (all_digits t)
       then Some
              (Z.eqb (digits_val s1 Big_int_Z.zero_big_int)
                (digits_val t Big_int_Z.zero_big_int))
       else Some (ceqs s1 t)
     | VBool c ->
       (match l with
        | VStr s2 -> Some (ceqs s2 (btext c))
        | _ -> None)
     | VList _ -> None
     | _ ->
       (match text_of r with
        | Some t ->
          if (&&) (all_digits s1) (all_digits t)
          then Some
                 (Z.eqb (digits_val s1 Big_int_Z.zero_big_int)
                   (digits_val t Big_int_Z.zero_big_int))
          else Some (ceqs s1 t)
        | None -> None))
  | VBool b ->
    (match r with
     | VNull -> Some false
     | VList _ -> None
     | _ ->
       (match to_bool r with
        | Some o -> (match o with
                     | Some c -> Some (eqb b c)
                     | None -> None)
        | None -> None))
  | VList _ -> (match r with
                | VNull -> Some false
                | _ -> None)
  | _ ->
    (match r with
     | VNull -> Some false
     | VBool c ->
       (match l with
        | VStr s1 -> Some (ceqs s1 (btext c))
        | _ -> None)
     | VList _ -> None
     | _ ->
       (match num_of l with
        | Some a ->
          (match num_of r with
           | Some b -> Some (match qcmp a b with
                             | Eq -> true
                             | _ -> false)
           | None -> Some false)
        | None -> None))

(** val ordv : val0 -> val0 -> comparison option **)

let ordv l r =
  match l with
  | VNull -> None
  | VStr s1 ->
    (match r with
     | VNull -> None
     | VBool _ -> None
     | VList _ -> None
     | _ -> (match text_of r with
             | Some t -> Some (scmp s1 t)
             | None -> None))
  | VBool _ -> None
  | VList _ -> None
  | _ ->
    (match r with
     | VNull -> None
     | VBool _ -> None
     | VList _ -> None
     | _ ->
       (match num_of l with
        | Some a ->
          (match num_of r with
           | Some b -> Some (qcmp a b)
           | None ->
             (match text_of l with
              | Some s1 ->
                (match text_of r with
                 | Some t -> Some (scmp s1 t)
                 | None -> None)
              | None -> None))
        | None -> None))

(** val has_double_comma : chars -> bool **)

let rec has_double_comma = function
| [] -> false
| c :: s' ->
  (match s' with
   | [] -> false
   | d :: _ -> (||) ((&&) (ceq c ',') (ceq d ',')) (has_double_comma s'))

(** val set_items : chars -> chars list option **)

let set_items s1 =
  let items = split_on ',' s1 in
  let empties =
    filter (fun w -> match w with
                     | [] -> true
                     | _ :: _ -> false) items
  in
  if existsb (fun w ->
       match w with
       | [] -> false
       | c :: _ ->
         (||) (is_ws c) (match rev w with
                         | [] -> false
                         | d :: _ -> is_ws d))
       items
  then None
  else (match empties with
        | [] -> Some items
        | _ :: _ -> if has_double_comma s1 then Some items else None)

(** val in_set : val0 -> chars -> bool option **)

let in_set l s1 =
  match set_items s1 with
  | Some items ->
    (match l with
     | VNull -> None
     | VStr t ->
       if (&&) (existsb all_digits items) (all_digits t)
       then None
       else Some (existsb (fun w -> ceqs t w) items)
     | VBool b ->
       let conv0 = map (fun w -> to_bool (VStr w)) items in
       if existsb (fun o ->
            match o with
            | Some y -> (match y with
                         | Some _ -> false
                         | None -> true)
            | None -> true) conv0
       then None
       else Some
              (existsb (fun o ->
                match o with
                | Some y -> (match y with
                             | Some c -> eqb b c
                             | None -> false)
                | None -> false) conv0)
     | VList _ -> None
     | _ ->
       let ns = map parse_dec items in
       (match num_of l with
        | Some a ->
          if existsb (fun o -> match o with
                               | Some _ -> false
                               | None -> true) ns
          then None
          else Some
                 (existsb (fun o ->
                   match o with
                   | Some b -> (match qcmp a b with
                                | Eq -> true
                                | _ -> false)
                   | None -> false) ns)
        | None -> None))
  | None -> None

(** val is_type : val0 -> chars -> bool option **)

let is_type l tn =
  let n0 =
    if prefix (str "java.lang.") tn
    then skipn (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ 0)))))))))) tn
    else tn
  in
  let isn = fun s1 -> ceqs n0 (str s1) in
  (match l with
   | VNull -> None
   | _ ->
     if (||) (isn "String") (isn "CharSequence")
     then Some (match l with
                | VStr _ -> true
                | _ -> false)
     else if isn "Integer"
          then Some (match l with
                     | VInt _ -> true
                     | _ -> false)
          else if isn "Long"
               then Some (match l with
                          | VLong _ -> true
                          | _ -> false)
               else if isn "Double"
                    then Some (match l with
                               | VDbl _ -> true
                               | _ -> false)
                    else if isn "Boolean"
                         then Some (match l with
                                    | VBool _ -> true
                                    | _ -> false)
                         else if isn "Number"
                              then Some (is_num l)
                              else if isn "Object"
                                   then Some true
                                   else if (||)
                                             (ceqs tn (str "java.util.List"))
                                             (ceqs tn
                                               (str "java.util.Collection"))
                                        then Some
                                               (match l with
                                                | VList _ -> true
                                                | _ -> false)
                                        else None)

(** val in_range : val0 -> chars -> bool option **)

let in_range l s1 =
  match find0 (str "..") s1 with
  | Some i ->
    let a = firstn i s1 in
    let b = skipn (add i (Stdlib.Int.succ (Stdlib.Int.succ 0))) s1 in
    if (&&) (all_digits a) (all_digits b)
    then let lo = digits_val a Big_int_Z.zero_big_int in
         let hi = digits_val b Big_int_Z.zero_big_int in
         if Z.ltb hi lo
         then None
         else (match l with
               | VInt z0 -> Some ((&&) (Z.leb lo z0) (Z.leb z0 hi))
               | VLong z0 -> Some ((&&) (Z.leb lo z0) (Z.leb z0 hi))
               | VDbl q ->
                 Some
                   ((&&)
                     (Z.leb
                       (Z.mul lo ((fun p -> Big_int_Z.shift_left_big_int p 1)
                         ((fun p -> Big_int_Z.shift_left_big_int p 1)
                         Big_int_Z.unit_big_int)))
                       q)
                     (Z.leb q
                       (Z.mul hi ((fun p -> Big_int_Z.shift_left_big_int p 1)
                         ((fun p -> Big_int_Z.shift_left_big_int p 1)
                         Big_int_Z.unit_big_int)))))
               | _ -> None)
    else None
  | None -> None

type reatom =
| RAny
| RDigit
| RCh of char
| RCls of char * char

type rquant =
| QOne
| QStar
| QPlus
| QRep of int

(** val rmatch1 : reatom -> char -> bool **)

let rmatch1 a c =
  match a with
  | RAny ->
    (&&)
      (negb
        ((=) (code c) (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
          (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
          (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ 0))))))))))))
      (negb
        ((=) (code c) (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
          (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
          (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
          (Stdlib.Int.succ (Stdlib.Int.succ 0)))))))))))))))
  | RDigit -> is_digit c
  | RCh d -> ceq c d
  | RCls (lo, hi) -> (&&) ((<=) (code lo) (code c)) ((<=) (code c) (code hi))

(** val rparse : int -> chars -> (reatom * rquant) list option **)

let rec rparse fuel s1 =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> None)
    (fun f ->
    match s1 with
    | [] -> Some []
    | _ :: _ ->
      let at_ =
        match s1 with
        | [] -> None
        | c :: r ->
          if ceq c '.'
          then Some (RAny, r)
          else if ceq c '\\'
               then (match r with
                     | [] -> None
                     | d :: r' ->
                       if ceq d 'd' then Some (RDigit, r') else None)
               else if ceq c '['
                    then (match r with
                          | [] -> None
                          | lo :: l ->
                            (match l with
                             | [] -> None
                             | m :: l0 ->
                               (match l0 with
                                | [] -> None
                                | hi :: l1 ->
                                  (match l1 with
                                   | [] -> None
                                   | e :: r' ->
                                     if (&&) (ceq m '-') (ceq e ']')
                                     then Some ((RCls (lo, hi)), r')
                                     else None))))
                    else if (||) (is_letter c) (is_digit c)
                         then Some ((RCh c), r)
                         else None
      in
      (match at_ with
       | Some p ->
         let (a, r) = p in
         let q =
           match r with
           | [] -> Some (QOne, [])
           | c :: r' ->
             if ceq c '*'
             then Some (QStar, r')
             else if ceq c '+'
                  then Some (QPlus, r')
                  else if ceq c '{'
                       then (match r' with
                             | [] -> None
                             | d :: l ->
                               (match l with
                                | [] -> None
                                | e :: r'' ->
                                  if (&&) (is_digit d) (ceq e '}')
                                  then Some ((QRep
                                         (sub (code d) (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ (Stdlib.Int.succ
                                           (Stdlib.Int.succ
                                           0)))))))))))))))))))))))))))))))))))))))))))))))))),
                                         r'')
                                  else None))
                       else Some (QOne, r)
         in
         (match q with
          | Some p0 ->
            let (qq, r') = p0 in
            (match rparse f r' with
             | Some rest -> Some ((a, qq) :: rest)
             | None -> None)
          | None -> None)
       | None -> None))
    fuel

(** val take_while_n : (char -> bool) -> int -> chars -> bool **)

let rec take_while_n p n0 s1 =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> true)
    (fun n' ->
    match s1 with
    | [] -> false
    | c :: s' -> (&&) (p c) (take_while_n p n' s'))
    n0

(** val rmatch : int -> (reatom * rquant) list -> chars -> bool **)

let rec rmatch fuel re s1 =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> false)
    (fun f ->
    match re with
    | [] -> (match s1 with
             | [] -> true
             | _ :: _ -> false)
    | p :: re' ->
      let (a, r) = p in
      (match r with
       | QOne ->
         (match s1 with
          | [] -> false
          | c :: s' -> (&&) (rmatch1 a c) (rmatch f re' s'))
       | QStar ->
         (||) (rmatch f re' s1)
           (match s1 with
            | [] -> false
            | c :: s' -> (&&) (rmatch1 a c) (rmatch f re s'))
       | QPlus ->
         (match s1 with
          | [] -> false
          | c :: s' -> (&&) (rmatch1 a c) (rmatch f ((a, QStar) :: re') s'))
       | QRep n0 ->
         (&&) (take_while_n (rmatch1 a) n0 s1) (rmatch f re' (skipn n0 s1))))
    fuel

(** val regex_f : val0 -> chars -> bool option **)

let regex_f l pat =
  match text_of l with
  | Some s1 ->
    (match rparse (Stdlib.Int.succ (length pat)) pat with
     | Some re ->
       (match l with
        | VNull -> None
        | VList _ -> None
        | _ ->
          Some
            (rmatch
              (mul
                (mul (Stdlib.Int.succ (length s1)) (Stdlib.Int.succ
                  (length re)))
                (Stdlib.Int.succ (Stdlib.Int.succ 0)))
              re s1))
     | None -> None)
  | None -> None

(** val string_op : (chars -> chars -> bool) -> val0 -> val0 -> bres **)

let string_op f l r =
  match l with
  | VNull -> BUns "string operator on null/list"
  | VList _ -> BUns "string operator on null/list"
  | _ ->
    (match text_of l with
     | Some a ->
       (match text_of r with
        | Some b -> BV (f a b)
        | None -> BUns "string operator on null right side")
     | None -> BUns "string operator on null right side")

(** val of_opt : string -> bool option -> bres **)

let of_opt why = function
| Some b -> BV b
| None -> BUns why

(** val neg : bres -> bres **)

let neg b = match b with
| BV x -> BV (negb x)
| _ -> b

