(** val text_value_split : binop -> val0 -> val0 -> string option **)

let text_value_split o l r =
  match l with
  | VStr s1 ->
    (match num_of_trim (VStr s1) with
     | Some a ->
       (match num_of_trim r with
        | Some b ->
          (match text_of r with
           | Some t ->
             let txt_eq =
               if (&&) (all_digits s1) (all_digits t)
               then Z.eqb (digits_val s1 Big_int_Z.zero_big_int)
                      (digits_val t Big_int_Z.zero_big_int)
               else ceqs s1 t
             in
             let val_eq = match qcmp a b with
                          | Eq -> true
                          | _ -> false in
             (match o with
              | OEq ->
                if eqb txt_eq val_eq
                then None
                else Some "DOC: == of numeric values, text vs value"
              | ONe ->
                if eqb txt_eq val_eq
                then None
                else Some "DOC: == of numeric values, text vs value"
              | OGt ->
                (match scmp s1 t with
                 | Eq ->
                   (match qcmp a b with
                    | Eq -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Lt ->
                   (match qcmp a b with
                    | Lt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Gt ->
                   (match qcmp a b with
                    | Gt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value"))
              | OGe ->
                (match scmp s1 t with
                 | Eq ->
                   (match qcmp a b with
                    | Eq -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Lt ->
                   (match qcmp a b with
                    | Lt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Gt ->
                   (match qcmp a b with
                    | Gt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value"))
              | OLt ->
                (match scmp s1 t with
                 | Eq ->
                   (match qcmp a b with
                    | Eq -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Lt ->
                   (match qcmp a b with
                    | Lt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Gt ->
                   (match qcmp a b with
                    | Gt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value"))
              | OLe ->
                (match scmp s1 t with
                 | Eq ->
                   (match qcmp a b with
                    | Eq -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Lt ->
                   (match qcmp a b with
                    | Lt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value")
                 | Gt ->
                   (match qcmp a b with
                    | Gt -> None
                    | _ ->
                      Some "DOC: ordering of numeric values, text vs value"))
              | _ -> None)
           | None -> None)
        | None -> None)
     | None -> None)
  | x ->
    (match num_of_trim x with
     | Some _ ->
       (match num_of_trim r with
        | Some _ ->
          (match r with
           | VStr t ->
             (match o with
              | OEq ->
                (match text_of l with
                 | Some s1 ->
                   if ceqs s1 t
                   then None
                   else Some
                          "KNOWN: number == numeric text written differently"
                 | None -> None)
              | ONe ->
                (match text_of l with
                 | Some s1 ->
                   if ceqs s1 t
                   then None
                   else Some
                          "KNOWN: number == numeric text written differently"
                 | None -> None)
              | _ -> None)
           | _ -> None)
        | None -> None)
     | None -> None)

(** val binop_eval : binop -> val0 -> val0 -> bool -> bres **)

let binop_eval o l r bare =
  if (&&) bare
       (negb (match o with
              | ORange -> true
              | ONRange -> true
              | _ -> false))
  then BUns "bare word on the right"
  else if bare
       then BUns "DOC: bare range"
       else (match text_value_split o l r with
             | Some w -> BUns w
             | None ->
               if (&&)
                    (match o with
                     | OCIc -> true
                     | ONCIc -> true
                     | OContains -> true
                     | ONContains -> true
                     | _ -> false)
                    (negb (match l with
                           | VStr _ -> true
                           | _ -> false))
               then BUns "GAP: contains on a non-String left side"
               else if match o with
                       | OIs ->
                         (match r with
                          | VStr t ->
                            (||)
                              ((||) (ceqs t (str "Number"))
                                (ceqs t (str "Object")))
                              (ceqs t (str "CharSequence"))
                          | _ -> false)
                       | ONIs ->
                         (match r with
                          | VStr t ->
                            (||)
                              ((||) (ceqs t (str "Number"))
                                (ceqs t (str "Object")))
                              (ceqs t (str "CharSequence"))
                          | _ -> false)
                       | _ -> false
                    then BUns "DOC: is shorthand"
                    else (match o with
                          | OEq -> of_opt "== on these kinds" (eqv l r)
                          | ONe -> neg (of_opt "!= on these kinds" (eqv l r))
                          | OEqIc ->
                            let b =
                              match l with
                              | VStr a ->
                                (match r with
                                 | VStr c ->
                                   if (&&) (all_digits a) (all_digits c)
                                   then BUns "GAP: =~ on digit texts"
                                   else BV (ceqs (lower a) (lower c))
                                 | _ -> BUns "=~ on a non-String")
                              | _ -> BUns "=~ on a non-String"
                            in
                            (match o with
                             | OEqIc -> b
                             | _ -> neg b)
                          | ONeIc ->
                            let b =
                              match l with
                              | VStr a ->
                                (match r with
                                 | VStr c ->
                                   if (&&) (all_digits a) (all_digits c)
                                   then BUns "GAP: =~ on digit texts"
                                   else BV (ceqs (lower a) (lower c))
                                 | _ -> BUns "=~ on a non-String")
                              | _ -> BUns "=~ on a non-String"
                            in
                            (match o with
                             | OEqIc -> b
                             | _ -> neg b)
                          | OCIc ->
                            string_op (fun a b -> occurs (lower b) (lower a))
                              l r
                          | ONCIc ->
                            neg
                              (string_op (fun a b ->
                                occurs (lower b) (lower a)) l r)
                          | OContains -> string_op (fun a b -> occurs b a) l r
                          | ONContains ->
                            neg (string_op (fun a b -> occurs b a) l r)
                          | OEnds -> string_op (fun a b -> suffix b a) l r
                          | ONEnds ->
                            neg (string_op (fun a b -> suffix b a) l r)
                          | OEquals -> string_op ceqs l r
                          | ONEquals -> neg (string_op ceqs l r)
                          | OIn ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "in: set or kinds" (in_set l s1)
                              | _ -> BUns "in: right not a text"
                            in
                            (match o with
                             | OIn -> b
                             | _ -> neg b)
                          | ONIn ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "in: set or kinds" (in_set l s1)
                              | _ -> BUns "in: right not a text"
                            in
                            (match o with
                             | OIn -> b
                             | _ -> neg b)
                          | OIs ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "is: type or null" (is_type l s1)
                              | _ -> BUns "is: right not a text"
                            in
                            (match o with
                             | OIs -> b
                             | _ -> neg b)
                          | ONIs ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "is: type or null" (is_type l s1)
                              | _ -> BUns "is: right not a text"
                            in
                            (match o with
                             | OIs -> b
                             | _ -> neg b)
                          | ORange ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "range: bounds or kinds"
                                  (in_range l s1)
                              | _ -> BUns "range: right not a text"
                            in
                            (match o with
                             | ORange -> b
                             | _ -> neg b)
                          | ONRange ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "range: bounds or kinds"
                                  (in_range l s1)
                              | _ -> BUns "range: right not a text"
                            in
                            (match o with
                             | ORange -> b
                             | _ -> neg b)
                          | ORegex ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "regex: pattern or kinds"
                                  (regex_f l s1)
                              | _ -> BUns "regex: right not a text"
                            in
                            (match o with
                             | ORegex -> b
                             | _ -> neg b)
                          | ONRegex ->
                            let b =
                              match r with
                              | VStr s1 ->
                                of_opt "regex: pattern or kinds"
                                  (regex_f l s1)
                              | _ -> BUns "regex: right not a text"
                            in
                            (match o with
                             | ORegex -> b
                             | _ -> neg b)
                          | OStarts -> string_op (fun a b -> prefix b a) l r
                          | ONStarts ->
                            neg (string_op (fun a b -> prefix b a) l r)
                          | _ ->
                            (match ordv l r with
                             | Some c ->
                               BV
                                 (match o with
                                  | OGt ->
                                    (match c with
                                     | Gt -> true
                                     | _ -> false)
                                  | OGe ->
                                    (match c with
                                     | Lt -> false
                                     | _ -> true)
                                  | OLt ->
                                    (match c with
                                     | Lt -> true
                                     | _ -> false)
                                  | OLe ->
                                    (match c with
                                     | Gt -> false
                                     | _ -> true)
                                  | _ -> false)
                             | None -> BUns "ordering on these kinds")))

(** val all_same : lop list -> lop option **)

let all_same = function
| [] -> None
| o :: os ->
  if forallb (fun o' ->
       match o with
       | LAnd -> (match o' with
                  | LAnd -> true
                  | LOr -> false)
       | LOr -> (match o' with
                 | LAnd -> false
                 | LOr -> true))
       os
  then Some o
  else None

(** val ltr : bool -> (lop * bool) list -> bool **)

let rec ltr b = function
| [] -> b
| p :: r ->
  let (l, c) = p in
  (match l with
   | LAnd -> ltr ((&&) b c) r
   | LOr -> ltr ((||) b c) r)

(** val prec_terms : bool -> (lop * bool) list -> bool list **)

let rec prec_terms cur = function
| [] -> cur :: []
| p :: r ->
  let (l, c) = p in
  (match l with
   | LAnd -> prec_terms ((&&) cur c) r
   | LOr -> cur :: (prec_terms c r))

(** val find_uns : bres list -> string option **)

let rec find_uns = function
| [] -> None
| b :: l' -> (match b with
              | BUns w -> Some w
              | _ -> find_uns l')

(** val combine_seq : bres -> (lop * bres) list -> bres **)

let combine_seq first rest =
  let all = first :: (map snd rest) in
  if existsb (fun b -> match b with
                       | BUns _ -> true
                       | _ -> false) all
  then (match find_uns all with
        | Some w -> BUns w
        | None -> BUns "?")
  else if existsb (fun b -> match b with
                            | BErr -> true
                            | _ -> false) all
       then (match all_same (map fst rest) with
             | Some l ->
               (match l with
                | LAnd ->
                  if existsb (fun b ->
                       match b with
                       | BV b0 -> if b0 then false else true
                       | _ -> false) all
                  then BUns "error next to a deciding false"
                  else BErr
                | LOr ->
                  if existsb (fun b -> match b with
                                       | BV b0 -> b0
                                       | _ -> false)
                       all
                  then BUns "error next to a deciding true"
                  else BErr)
             | None -> BUns "error in a mixed &&/|| sequence")
       else let v = fun b -> match b with
                             | BV x -> x
                             | _ -> false in
            let f = v first in
            let r = map (fun pat -> let (o, b) = pat in (o, (v b))) rest in
            let a = ltr f r in
            let p = existsb (fun x -> x) (prec_terms f r) in
            if eqb a p then BV a else BUns "&&/|| precedence"

(** val is_afun : atom -> bool **)

let is_afun = function
| AFun _ -> true
| _ -> false

(** val has_rest : prest -> bool **)

let has_rest = function
| PNil -> false
| PCons (_, _, _) -> true

(** val rest_has_afun : prest -> bool **)

let rec rest_has_afun = function
| PNil -> false
| PCons (_, a, r') -> (||) (is_afun a) (rest_has_afun r')

