type argv =
| AV of res * int
| AP of bres

(** val lit_arg : lit -> argv **)

let lit_arg = function
| LQ s1 ->
  AV
    ((if arg_lit_ok s1
      then q_value true s1
      else RUns "comma, parenthesis or quote inside a quoted argument"),
    (Stdlib.Int.succ 0))
| LNum z0 ->
  AV ((RV (VStr (ztext z0))), (Stdlib.Int.succ (Stdlib.Int.succ
    (Stdlib.Int.succ 0))))
| LNull ->
  AV ((RUns "bare null argument"), (Stdlib.Int.succ (Stdlib.Int.succ 0)))
| LBare s1 -> AV ((RV (VStr s1)), (Stdlib.Int.succ (Stdlib.Int.succ 0)))
| _ ->
  AV ((RUns "bare boolean argument"), (Stdlib.Int.succ (Stdlib.Int.succ 0)))

(** val lit_rhs : bool -> lit -> res * bool **)

let lit_rhs inb = function
| LQ s1 -> ((q_value inb s1), false)
| LNum z0 ->
  ((if in_int0 z0 then RV (VInt z0) else RUns "large constant"), false)
| LNull -> ((RV VNull), false)
| LTrue -> ((RV (VBool true)), false)
| LFalse -> ((RV (VBool false)), false)
| LBare s1 -> ((RV (VStr s1)), true)

(** val tern_lit : lit -> res **)

let tern_lit = function
| LQ s1 -> q_value true s1
| LNum z0 -> RLoose (ztext z0)
| LNull -> RV VNull
| LTrue -> RLoose (str "true")
| LFalse -> RLoose (str "false")
| LBare _ -> RUns "bare word as a ternary value"

(** val incdec : bool -> res -> res **)

let incdec inc r = match r with
| RV v ->
  (match v with
   | VInt z0 ->
     let z' =
       if inc
       then Z.add z0 Big_int_Z.unit_big_int
       else Z.sub z0 Big_int_Z.unit_big_int
     in
     if in_int0 z' then RV (VInt z') else RUns "++/-- overflow"
   | VLong z0 ->
     RV (VLong
       (if inc
        then Z.add z0 Big_int_Z.unit_big_int
        else Z.sub z0 Big_int_Z.unit_big_int))
   | _ -> RUns "++/-- of a value that is not an Integer or Long")
| RLoose _ -> RUns "++/-- of a loose value"
| _ -> r

(** val nm : chars -> string -> bool **)

let nm n0 s1 =
  ceqs n0 (str s1)

(** val arity : res **)

let arity =
  RUns "function arity outside the docs"

(** val body_text : exch -> (chars -> res) -> res **)

let body_text x k =
  bind_text (RV x.ex_body) k

(** val one_text : exch -> argv list -> (chars -> res) -> res **)

let one_text x a k =
  match a with
  | [] -> body_text x k
  | a0 :: l ->
    (match a0 with
     | AV (r, _) -> (match l with
                     | [] -> bind_text r k
                     | _ :: _ -> arity)
     | AP _ -> arity)

(** val one_val : exch -> argv list -> (val0 -> res) -> res **)

let one_val x a k =
  match a with
  | [] -> k x.ex_body
  | a0 :: l ->
    (match a0 with
     | AV (r, _) -> (match l with
                     | [] -> bind r k
                     | _ :: _ -> arity)
     | AP _ -> arity)

(** val with_int : res -> (Big_int_Z.big_int -> res) -> res **)

let with_int r k =
  bind_text r (fun s1 ->
    match parse_dec s1 with
    | Some d ->
      let (z0, n0) = d in
      ((fun fO fS n -> if n=0 then fO () else fS (n-1))
         (fun _ -> k z0)
         (fun _ -> RUns "number argument is not an integer")
         n0)
    | None -> RUns "number argument is not an integer")

(** val pv : bres -> res **)

let pv = function
| BV v -> RV (VBool v)
| BErr -> RErr
| BUns w -> RUns w

(** val call : exch -> chars -> argv list -> res **)

let call x n0 a =
  if nm n0 "trim"
  then one_text x a (fun s1 -> RV (VStr (trim s1)))
  else if nm n0 "uppercase"
       then one_text x a (fun s1 -> RV (VStr (upper s1)))
       else if nm n0 "lowercase"
            then one_text x a (fun s1 -> RV (VStr (lower s1)))
            else if nm n0 "capitalize"
                 then one_text x a capitalize
                 else if nm n0 "normalizeWhitespace"
                      then one_text x a normalize_ws
                      else if nm n0 "quote"
                           then one_text x a quote_f
                           else if nm n0 "unquote"
                                then one_text x a unquote_f
                                else if nm n0 "length"
                                     then one_text x a (fun s1 -> RV (VInt
                                            (Z.of_nat (length s1))))
                                     else if nm n0 "size"
                                          then one_val x a (fun v -> RV (VInt
                                                 (match v with
                                                  | VNull ->
                                                    Big_int_Z.zero_big_int
                                                  | VList l ->
                                                    Z.of_nat (length l)
                                                  | _ ->
                                                    Big_int_Z.unit_big_int)))
                                          else if nm n0 "isEmpty"
                                               then one_val x a (fun v ->
                                                      match v with
                                                      | VStr s1 ->
                                                        (match s1 with
                                                         | [] ->
                                                           RV (VBool
                                                             (match v with
                                                              | VNull -> true
                                                              | VStr s2 ->
                                                                (match s2 with
                                                                 | [] -> true
                                                                 | _ :: _ ->
                                                                   false)
                                                              | VList l ->
                                                                (match l with
                                                                 | [] -> true
                                                                 | _ :: _ ->
                                                                   false)
                                                              | _ -> false))
                                                         | _ :: t ->
                                                           if blank t
                                                           then RUns
                                                                  "DOC: isEmpty of a blank text"
                                                           else RV (VBool
                                                                  false))
                                                      | _ ->
                                                        RV (VBool
                                                          (match v with
                                                           | VNull -> true
                                                           | VStr s1 ->
                                                             (match s1 with
                                                              | [] -> true
                                                              | _ :: _ ->
                                                                false)
                                                           | VList l ->
                                                             (match l with
                                                              | [] -> true
                                                              | _ :: _ ->
                                                                false)
                                                           | _ -> false)))
                                               else if nm n0 "isNumeric"
                                                    then one_text x a
                                                           (all_of is_digit)
                                                    else if nm n0 "isAlpha"
                                                         then one_text x a
                                                                (all_of
                                                                  is_letter)
                                                         else if nm n0
                                                                   "isAlphaNumeric"
                                                              then one_text x
                                                                    a
                                                                    (all_of
                                                                    (fun c ->
                                                                    (||)
                                                                    (is_letter
                                                                    c)
                                                                    (is_digit
                                                                    c)))
                                                              else if 
                                                                    nm n0
                                                                    "contains"
                                                                   then 
                                                                    let k =
                                                                    fun s1 t ->
                                                                    match t with
                                                                    | [] ->
                                                                    RUns
                                                                    "GAP: contains() with an empty text"
                                                                    | _ :: _ ->
                                                                    (match s1 with
                                                                    | [] ->
                                                                    RUns
                                                                    "GAP: contains() with an empty text"
                                                                    | _ :: _ ->
                                                                    RV (VBool
                                                                    (occurs
                                                                    (lower t)
                                                                    (lower s1))))
                                                                    in
                                                                    (
                                                                    match a with
                                                                    | [] ->
                                                                    arity
                                                                    | a0 :: l ->
                                                                    (match a0 with
                                                                    | AV (
                                                                    e, _) ->
