(** val ev : exch -> fn -> res **)

let rec ev x = function
| FBody -> RV x.ex_body
| FHeader (_, k) -> RV (hget k x.ex_headers)
| FProp (_, k) -> RV (lookup k x.ex_props)
| FVar k -> RV (lookup k x.ex_vars)
| FNull -> RV VNull
| FHeadersSize -> RV (VInt (Z.of_nat (length x.ex_headers)))
| FTyped (t, g) -> bind (ev x g) (typed t)
| FCall (n0, _, a) -> call x n0 (evargs x a)
| FPred p ->
  let PS (a, rest) = p in
  (match a with
   | AFun g ->
     (match rest with
      | PNil -> ev x g
      | PCons (_, _, _) -> pv (evps true x p))
   | _ -> pv (evps true x p))
| FTern (c, t, e) ->
  let PS (a, rest) = c in
  (match a with
   | AFun _ ->
     (match rest with
      | PNil ->
        RUns
          "GAP: a lone function as the ternary condition (refused by Camel)"
      | PCons (_, _, _) ->
        (match evps true x c with
         | BV b -> if b then evtv x t else evtv x e
         | BErr -> RErr
         | BUns w -> RUns w))
   | _ ->
     (match evps true x c with
      | BV b -> if b then evtv x t else evtv x e
      | BErr -> RErr
      | BUns w -> RUns w))

(** val evargs : exch -> args -> argv list **)

and evargs x = function
| ANil -> []
| ACons (y, r) -> (evarg x y) :: (evargs x r)

(** val evarg : exch -> arg -> argv **)

and evarg x = function
| AFn f -> AV ((ev x f), 0)
| ALit l -> lit_arg l
| APred p -> AP (evps false x p)

(** val evtv : exch -> tval -> res **)

and evtv x = function
| TVLit l -> tern_lit l
| TVFn f -> ev x f

(** val evatom : bool -> exch -> atom -> bres **)

and evatom inb x = function
| ACmp (l, o, r) ->
  (match evlhs inb x l with
   | RV u ->
     let (r1, bare) = evrhs inb x r in
     (match r1 with
      | RV v -> binop_eval o u v bare
      | RLoose _ -> BUns "loose operand"
      | RErr -> BErr
      | RUns w -> BUns w)
   | RLoose _ ->
     let (r1, _) = evrhs inb x r in
     (match r1 with
      | RErr -> BErr
      | RUns w -> BUns w
      | _ -> BUns "loose operand")
   | RErr -> BErr
   | RUns w ->
     let (r1, _) = evrhs inb x r in (match r1 with
                                     | RErr -> BErr
                                     | _ -> BUns w))
| ANot f ->
  (match ev x f with
   | RV v -> neg (truth v)
   | RLoose _ -> BUns "loose"
   | RErr -> BErr
   | RUns w -> BUns w)
| AFun f ->
  (match ev x f with
   | RV v -> truth v
   | RLoose _ -> BUns "loose"
   | RErr -> BErr
   | RUns w -> BUns w)
| ANot2 f ->
  if inb
  then (match ev x f with
        | RV v -> truth v
        | RLoose _ -> BUns "loose"
        | RErr -> BErr
        | RUns w -> BUns w)
  else BErr

(** val evlhs : bool -> exch -> lhs -> res **)

and evlhs inb x = function
| LFn f ->
  (match f with
   | FNull ->
     if inb
     then RUns "GAP: null as the left side inside the braces"
     else RV VNull
   | _ -> ev x f)
| LInc f -> if inb then RUns "++ inside the braces" else incdec true (ev x f)
| LDecr f ->
  if inb then RUns "-- inside the braces" else incdec false (ev x f)
| LNotFn _ -> if inb then RUns "!f OP r inside the braces" else RErr

(** val evrhs : bool -> exch -> rhs -> res * bool **)

and evrhs inb x = function
| RLit l -> lit_rhs inb l
| RFn f ->
  if inb
  then ((RUns "function on the right inside the braces"), false)
  else ((ev x f), false)
| RNot _ ->
  ((if inb then RUns "!f on the right inside the braces" else RErr), false)

(** val evps : bool -> exch -> pseq -> bres **)

and evps inb x = function
| PS (a, r) ->
  if (&&) ((&&) inb (has_rest r)) ((||) (is_afun a) (rest_has_afun r))
  then BUns "GAP: a lone function as an operand inside the braces"
  else combine_seq (evatom inb x a) (evrest inb x r)

(** val evrest : bool -> exch -> prest -> (lop * bres) list **)

and evrest inb x = function
| PNil -> []
| PCons (o, a, r') -> (o, (evatom inb x a)) :: (evrest inb x r')

(** val vtext : res -> (chars option, string) sum **)

let vtext = function
| RV v ->
  (match v with
   | VNull -> Inl (Some [])
   | _ ->
     (match text_of v with
      | Some s1 -> Inl (Some s1)
      | None -> Inr "list in a template"))
| RLoose s1 -> Inl (Some s1)
| RErr -> Inl None
| RUns w -> Inr w

(** val template : exch -> part list -> res **)

let rec template x = function
| [] -> RV (VStr [])
| p :: t' ->
  let here =
    match p with
    | TText s1 ->
      if (||) (occurs (str "?:") s1) (occurs (str "~>") s1)
      then Inr "elvis/chain operator in text"
      else (match unesc false s1 with
            | Some v -> Inl (Some v)
            | None -> Inr "escape or $ in text")
    | TFn (_, f) -> vtext (ev x f)
    | TPost (f, inc) -> vtext (incdec inc (ev x f))
  in
  (match here with
   | Inl o ->
     (match o with
      | Some a ->
        (match template x t' with
         | RV v -> (match v with
                    | VStr b -> RV (VStr (app a b))
                    | x0 -> RV x0)
         | x0 -> x0)
      | None -> RErr)
   | Inr w -> RUns w)

(** val elvis_default : lit -> res **)

let elvis_default = function
| LQ s1 -> q_value false s1
| LNum z0 -> RLoose (ztext z0)
| LNull -> RUns "GAP: elvis default null"
| _ -> RUns "elvis default kind"

(** val chain : bool -> exch -> res -> fn list -> res **)

let rec chain ns x r = function
| [] -> r
| g :: fs' ->
  (match r with
   | RV v ->
     (match v with
      | VNull ->
        if ns then RV VNull else chain ns x (ev (with_body x VNull) g) fs'
      | _ -> chain ns x (ev (with_body x v) g) fs')
   | RLoose _ -> RUns "chain of a loose value"
   | _ -> r)

(** val nargs : args -> int **)

let rec nargs = function
| ANil -> 0
| ACons (_, r) -> Stdlib.Int.succ (nargs r)

(** val arity_ok : chars -> int -> bool -> bool **)

let arity_ok n0 k first_pred =
  let one0 =
    existsb (fun m -> nm n0 m)
      ("trim" :: ("uppercase" :: ("lowercase" :: ("capitalize" :: ("normalizeWhitespace" :: ("quote" :: ("unquote" :: ("length" :: ("size" :: ("isEmpty" :: ("isNumeric" :: ("isAlpha" :: ("isAlphaNumeric" :: [])))))))))))))
  in
  if one0
  then (&&) ((<=) k (Stdlib.Int.succ 0)) (negb first_pred)
  else if (||)
            ((||) ((||) (nm n0 "contains") (nm n0 "substringBefore"))
              (nm n0 "substringAfter"))
            (nm n0 "escape")
       then (&&)
              ((||) ((=) k (Stdlib.Int.succ 0))
                ((=) k (Stdlib.Int.succ (Stdlib.Int.succ 0))))
              (negb first_pred)
       else if nm n0 "substring"
            then (&&)
                   ((&&) ((<=) (Stdlib.Int.succ 0) k)
                     ((<=) k (Stdlib.Int.succ (Stdlib.Int.succ
                       (Stdlib.Int.succ 0)))))
                   (negb first_pred)
            else if (||)
                      ((||)
                        ((||) (nm n0 "substringBetween") (nm n0 "replace"))
                        (nm n0 "concat"))
                      (nm n0 "pad")
                 then (&&)
                        ((||) ((=) k (Stdlib.Int.succ (Stdlib.Int.succ 0)))
                          ((=) k (Stdlib.Int.succ (Stdlib.Int.succ
                            (Stdlib.Int.succ 0)))))
                        (negb first_pred)
                 else if nm n0 "not"
                      then (||) ((=) k 0)
                             ((&&) ((=) k (Stdlib.Int.succ 0)) first_pred)
                      else if nm n0 "iif"
                           then (&&)
                                  ((=) k (Stdlib.Int.succ (Stdlib.Int.succ
                                    (Stdlib.Int.succ 0))))
                                  first_pred
                           else if nm n0 "val"
                                then (&&) ((=) k (Stdlib.Int.succ 0))
                                       (negb first_pred)
                                else false

(** val first_is_pred : args -> bool **)

let first_is_pred = function
| ANil -> false
| ACons (a0, _) -> (match a0 with
                    | APred _ -> true
                    | _ -> false)

(** val orelse : string option -> string option -> string option **)

let orelse a b =
  match a with
  | Some _ -> a
  | None -> b

(** val chk_lit : bool -> bool -> lit -> string option **)

let chk_lit infn isarg = function
| LQ s1 ->
  if existsb (fun c -> ceq c '\'') s1
  then Some "quote inside a quoted literal"
  else if (&&) isarg (negb (arg_lit_ok s1))
       then Some "comma, parenthesis or quote inside a quoted argument"
       else (match unesc infn s1 with
             | Some _ -> None
             | None -> Some "escape, $ or brace in a literal")
| _ -> None

(** val is_typed : fn -> bool **)

let is_typed = function
| FTyped (_, _) -> true
| _ -> false

(** val is_pred_fn : fn -> bool **)

let is_pred_fn = function
| FTyped (_, f0) ->
  (match f0 with
   | FPred _ -> true
   | FTern (_, _, _) -> true
   | _ -> false)
| FPred _ -> true
| FTern (_, _, _) -> true
| _ -> false

(** val is_lone : atom -> bool **)

let is_lone = function
| ACmp (_, _, _) -> false
| _ -> true

(** val args_have_fn : args -> bool **)

let rec args_have_fn = function
| ANil -> false
| ACons (a0, r) -> (match a0 with
                    | AFn _ -> true
                    | _ -> args_have_fn r)

(** val atom_nested_call : atom -> bool **)

let atom_nested_call = function
| ACmp (l, _, _) ->
  (match l with
   | LFn f -> (match f with
               | FCall (_, _, g) -> args_have_fn g
               | _ -> false)
   | _ -> false)
| ANot f -> (match f with
             | FCall (_, _, g) -> args_have_fn g
             | _ -> false)
| AFun f -> (match f with
             | FCall (_, _, g) -> args_have_fn g
             | _ -> false)
| ANot2 f -> (match f with
              | FCall (_, _, g) -> args_have_fn g
              | _ -> false)

(** val rest_nested_call : prest -> bool **)

let rec rest_nested_call = function
| PNil -> false
| PCons (_, a, r') -> (||) (atom_nested_call a) (rest_nested_call r')

(** val ps_nested_call : pseq -> bool **)

let ps_nested_call = function
| PS (a, r) -> (||) (atom_nested_call a) (rest_nested_call r)

(** val splits_args : chars -> bool **)

let splits_args n0 =
  existsb (fun m -> nm n0 m)
    ("contains" :: ("substring" :: ("substringBefore" :: ("substringAfter" :: ("substringBetween" :: ("replace" :: ("concat" :: ("pad" :: ("escape" :: ("iif" :: []))))))))))

(** val args_nested_comma : args -> bool **)

let rec args_nested_comma = function
| ANil -> false
| ACons (a0, r) ->
  (match a0 with
   | AFn f -> (||) (occurs (',' :: []) (rfn f)) (args_nested_comma r)
   | _ -> args_nested_comma r)

(** val args_nested_quoted_pred : args -> bool **)

let rec args_nested_quoted_pred = function
| ANil -> false
| ACons (a0, r) ->
  (match a0 with
   | AFn f ->
     (match f with
      | FPred _ ->
        (||) (occurs ('\'' :: []) (rfn f)) (args_nested_quoted_pred r)
      | FTern (_, _, _) ->
        (||) (occurs ('\'' :: []) (rfn f)) (args_nested_quoted_pred r)
      | _ -> args_nested_quoted_pred r)
   | _ -> args_nested_quoted_pred r)

(** val args_have_brace_escape : args -> bool **)

let rec args_have_brace_escape = function
| ANil -> false
| ACons (y, r) ->
  (||)
    (occurs
      ((ascii_of_nat (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
         (Stdlib.Int.succ
         0))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))) :: ('}' :: []))
      (rarg y))
    (args_have_brace_escape r)

(** val chkop : binop -> rhs -> string option **)

let chkop o r =
  match o with
  | OIs ->
    (match r with
     | RLit l ->
       (match l with
        | LNum _ -> Some "number on the right of is/range"
        | LBare _ -> Some "bare word on the right"
        | _ -> None)
     | _ -> None)
  | ONIs ->
    (match r with
     | RLit l ->
       (match l with
        | LNum _ -> Some "number on the right of is/range"
        | LBare _ -> Some "bare word on the right"
        | _ -> None)
     | _ -> None)
  | ORange ->
    (match r with
     | RLit l ->
       (match l with
        | LNum _ -> Some "number on the right of is/range"
        | _ -> None)
     | _ -> None)
  | ONRange ->
    (match r with
     | RLit l ->
       (match l with
        | LNum _ -> Some "number on the right of is/range"
        | _ -> None)
     | _ -> None)
  | _ ->
    (match r with
     | RLit l ->
       (match l with
        | LBare _ -> Some "bare word on the right"
        | _ -> None)
     | _ -> None)

(** val chkf : fn -> string option **)

let rec chkf = function
| FTyped (_, g) -> chkf g
| FCall (n0, _, a) ->
  if negb (arity_ok n0 (nargs a) (first_is_pred a))
  then Some "function form outside the docs"
  else if (&&) (splits_args n0) (args_nested_comma a)
       then Some
              "MINOR: nested function with a comma inside a function of several arguments"
       else if args_nested_quoted_pred a
            then Some
                   "MINOR: nested predicate with a quoted literal in a function argument"
            else if args_have_brace_escape a
                 then Some "GAP: \\} inside a function argument"
                 else if (&&) (nm n0 "escape")
                           (negb
                             (match a with
                              | ANil -> false
                              | ACons (a0, _) ->
                                (match a0 with
                                 | ALit l ->
                                   (match l with
                                    | LBare k ->
                                      existsb (fun m ->
                                        ceqs (lower k) (str m))
                                        ("html" :: ("xml" :: ("json" :: ("js" :: ("javascript" :: ("sql" :: ("url" :: [])))))))
                                    | _ -> false)
                                 | _ -> false)))
                      then (match a with
                            | ANil -> Some "escape kind outside the docs"
                            | ACons (a0, _) ->
                              (match a0 with
                               | ALit l ->
                                 (match l with
                                  | LQ _ ->
                                    Some "MINOR: escape with a quoted kind"
                                  | _ -> Some "escape kind outside the docs")
                               | _ -> Some "escape kind outside the docs"))
                      else chkargs (first_is_pred a) a
| FPred p ->
  orelse
    (let PS (a, _) = p in
     (match a with
      | ACmp (l, _, _) ->
        (match l with
         | LFn g ->
           if is_typed g
           then Some "GAP: typed prefix on the left inside the braces"
           else None
         | _ -> None)
      | _ -> None))
    (chkps true p)
| FTern (c, t, e) ->
  orelse
    (let PS (a, rest) = c in
     (match rest with
      | PNil ->
        if is_lone a
        then Some "GAP: a lone or negated function as the ternary condition"
        else None
      | PCons (_, _, _) -> None))
    (orelse
      (if ps_nested_call c
       then Some
              "MINOR: ternary condition with a function that has a nested ${ } argument"
       else None)
      (orelse (chkps true c) (orelse (chktv t) (chktv e))))
| _ -> None

(** val chkargs : bool -> args -> string option **)

and chkargs first = function
| ANil -> None
| ACons (y, r) ->
  (match y with
   | APred p ->
     if first
     then orelse (chkps_infn p) (chkargs false r)
     else Some "function form outside the docs"
   | _ -> orelse (chka y) (chkargs false r))

(** val chkps_infn : pseq -> string option **)

and chkps_infn = function
| PS (a, r) -> orelse (chkatom_infn true a) (chkrest_infn r)

(** val chkrest_infn : prest -> string option **)

and chkrest_infn = function
| PNil -> None
| PCons (_, a, r') -> orelse (chkatom_infn false a) (chkrest_infn r')

(** val chkatom_infn : bool -> atom -> string option **)

and chkatom_infn first = function
| ACmp (l, o, r) ->
  orelse (chkop o r)
    (orelse
      (match l with
       | LFn _ -> None
       | LNotFn _ -> None
       | _ -> Some "GAP: ++/-- in a predicate argument (refused by Camel)")
      (orelse (chkl false first l)
        (match r with
         | RLit li -> chk_lit true false li
         | RFn f -> chkf f
         | RNot f -> chkf f)))
| ANot f -> chkf f
| AFun f -> chkf f
| ANot2 f -> chkf f

(** val chka : arg -> string option **)

and chka = function
| AFn f -> chkf f
| ALit l -> chk_lit true true l
| APred p -> chkps false p

(** val chktv : tval -> string option **)

and chktv = function
| TVLit l -> chk_lit true false l
| TVFn f -> chkf f

(** val chkatom : bool -> bool -> atom -> string option **)

and chkatom inb first a =
  if (&&) inb
       (match a with
        | ACmp (l, _, _) -> (match l with
                             | LFn f -> is_pred_fn f
                             | _ -> false)
        | ANot f -> is_pred_fn f
        | AFun f -> is_pred_fn f
        | ANot2 f -> is_pred_fn f)
  then Some
         "a predicate nested inside the braces without its own ${ } (ambiguous text)"
  else (match a with
        | ACmp (l, o, r) ->
          orelse (chkop o r)
            (orelse
              (match l with
               | LFn f ->
                 (match f with
                  | FNull ->
                    if inb
                    then Some "GAP: null as the left side inside the braces"
                    else None
                  | _ -> None)
               | _ -> None)
              (orelse (chkl inb first l) (chkr inb r)))
        | ANot f ->
          if (&&) inb (is_typed f)
          then Some "MINOR: negated typed function inside the braces"
          else if (&&) inb
                    (match f with
                     | FCall (_, _, g) -> args_have_fn g
                     | _ -> false)
               then Some
                      "GAP: negated call with a nested argument inside the braces"
               else chkf f
        | AFun f -> chkf f
        | ANot2 f ->
          if (&&) inb (is_typed f)
          then Some "MINOR: negated typed function inside the braces"
          else if (&&) inb
                    (match f with
                     | FCall (_, _, g) -> args_have_fn g
                     | _ -> false)
               then Some
                      "GAP: negated call with a nested argument inside the braces"
               else chkf f)

(** val chkl : bool -> bool -> lhs -> string option **)

and chkl inb first = function
| LFn f -> chkf f
| LInc f ->
  if inb
  then Some "GAP: ++/-- inside the braces"
  else if negb first then Some "MINOR: ++/-- after && / ||" else chkf f
| LDecr f ->
  if inb
  then Some "GAP: ++/-- inside the braces"
  else if negb first then Some "MINOR: ++/-- after && / ||" else chkf f
| LNotFn f -> chkf f

(** val chkr : bool -> rhs -> string option **)

and chkr inb = function
| RLit l -> chk_lit inb false l
| RFn f -> chkf f
| RNot f -> chkf f

(** val chkps : bool -> pseq -> string option **)

and chkps inb = function
| PS (a, r) ->
  if (&&) ((&&) inb (has_rest r)) ((||) (is_afun a) (rest_has_afun r))
  then Some "GAP: a lone function as an operand inside the braces"
  else orelse (chkatom inb true a) (chkrest inb r)

(** val chkrest : bool -> prest -> string option **)

and chkrest inb = function
| PNil -> None
| PCons (_, a, r') -> orelse (chkatom inb false a) (chkrest inb r')

(** val chkpart : part -> string option **)

let chkpart = function
| TText _ -> None
| TFn (_, f) -> chkf f
| TPost (f, _) -> chkf f

(** val chkparts : part list -> string option **)

let rec chkparts = function
| [] -> None
| p :: r -> orelse (chkpart p) (chkparts r)

(** val chkfs : fn list -> string option **)

let rec chkfs = function
| [] -> None
| f :: r -> orelse (chkf f) (chkfs r)

(** val chkprog : prog -> string option **)

let chkprog = function
| PExpr t -> chkparts t
| PPred q -> chkps false q
| PElvis (f, d) -> orelse (chkf f) (chk_lit false false d)
| PChain (_, f, fs) -> chkfs (f :: fs)

(** val norm_parts : part list -> part list **)

let rec norm_parts = function
| [] -> []
| p :: r ->
  (match p with
   | TText a ->
     (match a with
      | [] -> norm_parts r
      | _ :: _ ->
        (match norm_parts r with
         | [] -> (TText a) :: []
         | p0 :: r' ->
           (match p0 with
            | TText b -> (TText (app a b)) :: r'
            | x -> (TText a) :: (x :: r'))))
   | _ -> p :: (norm_parts r))

