  let h i = (n land (1 lsl i)) <> 0 in
  f (h 0) (h 1) (h 2) (h 3) (h 4) (h 5) (h 6) (h 7))
                                                             (fun b7 b8 b9 b10 b11 b12 b13 b14 ->
                                                             if b7
                                                             then if b8
                                                                  then 
                                                                    post_glued
                                                                    r
                                                                  else 
                                                                    if b9
                                                                    then 
                                                                    if b10
                                                                    then 
