                                                                    LUns0 w
                                                                    else 
                                                                    LUns0 w)
                                                                    a1)
                                                                    s3)
                                                                    else 
                                                                    LUns0 w
                                                                    else 
                                                                    LUns0 w
                                                                    else 
                                                                    LUns0 w)
                                                                    a0)
                                                                    s2)
                                                               else LUns0 w
                                      else LUns0 w)
                                      a)
                                    w))
                            | Inr w -> LUns0 w)
                         | Inr w -> LUns0 w)
                 | None -> LUns0 "TK: input text")
              | VList _ -> LUns0 "TK: the toString() of a List input")
           | Inr w -> LUns0 w))

type lexp =
| XConstant of chars * chars option * bool
| XHeader of chars * bool
| XProp of chars * bool
| XVar of chars * bool
| XRef of chars * chars option * bool
| XTokenize of tkopts * chars option

(** val eval : lenv -> lexp -> lres **)

let eval x = function
| XConstant (t, r, tr) -> ev_constant x t r tr
| XHeader (n0, tr) -> ev_header x n0 tr
| XProp (n0, tr) -> ev_prop x n0 tr
| XVar (n0, tr) -> ev_var x n0 tr
| XRef (n0, r, tr) -> ev_ref x n0 r tr false
| XTokenize (o, r) -> ev_tokenize x o r

(** val evalp : lenv -> lexp -> lres **)

let evalp x e = match e with
| XRef (n0, r, tr) -> ev_ref x n0 r tr true
| XTokenize (_, _) -> LUns0 "TK: tokenize as a predicate"
| _ -> as_pred (eval x e)

type expr =
| XSimple of prog
| XLang of lexp

type eres =
| EV of val0
| EUns of string

(** val sview : exchange -> exch **)

let sview x =
  { ex_body = x.x_msg.m_body; ex_headers = x.x_msg.m_headers; ex_props =
    x.x_props; ex_vars = x.x_vars }

(** val lenv_of : exchange -> lenv **)

let lenv_of x =
  { le_body = x.x_msg.m_body; le_headers = x.x_msg.m_headers; le_xprops =
    x.x_props; le_vars = x.x_vars; le_gvars = []; le_groups = []; le_reg = [];
    le_pp = (penv0 []) }

(** val lang_scoped : lexp -> bool **)

let lang_scoped = function
| XVar (n0, _) -> existsb (fun c -> ceq c ':') n0
| XRef (_, _, _) -> true
| _ -> false

(** val eval_expr : exchange -> expr -> eres **)

let eval_expr x = function
| XSimple p ->
  (match run (sview x) p with
   | RV v -> EV v
   | RLoose _ ->
     EUns "L2: a Simple value whose Java type is not documented is stored"
   | RErr ->
     EUns "L2: Simple error (startup vs runtime failure not modelled yet)"
   | RUns w -> EUns w)
| XLang l ->
  if lang_scoped l
  then EUns
         "L2: variable repositories / registry in a language expression not connected"
  else (match eval (lenv_of x) l with
        | LV v -> EV v
        | LErr _ ->
          EUns
            "L2: a language error (startup vs runtime failure not modelled yet)"
        | LUns0 w -> EUns w)

type pres0 =
| PB of bool
| PUns0 of string

(** val eval_pred : exchange -> expr -> pres0 **)

let eval_pred x e = match e with
| XSimple p ->
  if is_predicate p
  then (match eval_expr x e with
        | EV v ->
          (match v with
           | VBool b -> PB b
           | _ -> PUns0 "L2: a Simple predicate gave a non-boolean")
        | EUns w -> PUns0 w)
  else PUns0 "L2: a Simple expression (not a predicate) used as a predicate"
| XLang l ->
  if lang_scoped l
  then PUns0
         "L2: variable repositories / registry in a language predicate not connected"
  else (match evalp (lenv_of x) l with
        | LV v ->
          (match v with
           | VBool b -> PB b
           | _ -> PUns0 "L2: a language predicate gave a non-boolean")
        | LErr _ -> PUns0 "L2: a language predicate error"
        | LUns0 w -> PUns0 w)

type strat =
| StNone
| StLatest
| StOriginal
| StGroupedBody

type split_opts = { sp_stop : bool; sp_group : int option; sp_delim : 
                    chars; sp_maxfail : int option; sp_strat : strat }

type agg_opts = { ago_id : chars; ago_corr : expr; ago_strat : strat;
                  ago_size : int option; ago_pred : expr option;
                  ago_eager : bool; ago_close : bool }

type lbkind =
| LBRoundRobin
| LBFailover of chars list * Big_int_Z.big_int

type endpoint =
| EDirect of chars
| EMock of chars

type step =
| SSetBody of expr
| STransform of expr
| SSetHeader of chars * expr
| SSetProperty of chars * expr
| SSetVariable of chars * expr
| SRemoveHeader of chars
| SRemoveHeaders of chars * chars list
| SRemoveProperty of chars
| SRemoveVariable of chars
| SFilter of expr * step list
| SChoice of (expr * step list) list * step list option
| SPipeline of step list
| STo of endpoint
| SStop
| SThrow of chars * chars
| SDoTry of step list * ((chars list * expr option) * step list) list
   * step list option
| SSplit of expr * split_opts * step list
| SMulticast of strat * step list
| SRecipientList of strat * expr * chars
| SAggregate of agg_opts * step list
| SLoop of expr * bool * bool * step list
| SIdem of chars * expr * bool * bool * step list
| SLB of chars * lbkind * step list
| SRoutingSlip of expr * chars
| SDynamicRouter of expr * chars
| SConvertBody of jtype * bool

type route = { r_id : chars; r_from : chars; r_steps : step list }

type clause = { c_ex : chars list; c_when : expr option;
                c_handled : bool option; c_continued : bool;
                c_redeliveries : int; c_steps : step list }

type uomode =
| UONone
| UOMessage
| UOBody

type ehconf =
| EHDefault
| EHDlc of chars * int * uomode

type octrig =
| OcAlways
| OcComplete
| OcFailure

type oncomp = { oc_trig : octrig; oc_when : expr option; oc_before : 
                bool; oc_orig : bool; oc_steps : step list }

type event =
| EvMock of chars * exchange * bool

(** val unknown_exn : event list -> event list **)

let unknown_exn t =
  map (fun pat -> let EvMock (n0, y, _) = pat in EvMock (n0, y, true)) t

(** val any_instance : chars -> chars list -> bool r0 **)

let rec any_instance c = function
| [] -> Ok0 false
| t :: r ->
  (match instance_of c t with
   | Ok0 a -> if a then Ok0 true else any_instance c r
   | Uns0 w -> Uns0 w)

(** val chain_instance : exn list -> chars list -> bool r0 **)

let rec chain_instance es ts =
  match es with
  | [] -> Ok0 false
  | e :: r ->
    (match any_instance (exn_class e) ts with
     | Ok0 a -> if a then Ok0 true else chain_instance r ts
     | Uns0 w -> Uns0 w)

(** val select_catch :
    exchange -> exn -> ((chars list * expr option) * step list) list -> step
    list option r0 **)

let rec select_catch x e = function
| [] -> Ok0 None
| p :: r ->
  let (p0, ss) = p in
  let (ts, w) = p0 in
  (match chain_instance (exn_chain e) ts with
   | Ok0 a ->
     if a
     then (match w with
           | Some p1 ->
             (match eval_pred x p1 with
              | PB b -> if b then Ok0 (Some ss) else select_catch x e r
              | PUns0 why -> Uns0 why)
           | None -> Ok0 (Some ss))
     else select_catch x e r
   | Uns0 why -> Uns0 why)

(** val split_items : split_opts -> val0 -> val0 list r0 **)

let split_items o v = match v with
| VNull -> Uns0 "SPL: splitting null not documented"
| VStr s1 ->
  if ceqs o.sp_delim (str "false")
  then Ok0 ((VStr s1) :: [])
  else (match o.sp_delim with
        | [] -> Uns0 "SPL: delimiter of several characters not modelled"
        | d :: l ->
          (match l with
           | [] ->
             (match s1 with
              | [] -> Uns0 "SPL: splitting the empty String not documented"
              | _ :: _ ->
                let parts = split_on d s1 in
                if existsb (fun p ->
                     match p with
                     | [] -> true
                     | _ :: _ -> false) parts
                then Uns0 "SPL: empty items between delimiters not documented"
                else Ok0 (map (fun x -> VStr x) parts))
           | _ :: _ ->
             Uns0 "SPL: delimiter of several characters not modelled"))
| VList l -> Ok0 (map (fun x -> VStr x) l)
| _ -> Ok0 (v :: [])

(** val chunk_f : int -> int -> chars list -> chars list list **)

let rec chunk_f fuel n0 l =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> [])
    (fun f ->
    match l with
    | [] -> []
    | _ :: _ -> (firstn n0 l) :: (chunk_f f n0 (skipn n0 l)))
    fuel

(** val texts : val0 list -> chars list option **)

let rec texts = function
| [] -> Some []
| v :: r ->
  (match v with
   | VStr s1 -> option_map (fun x -> s1 :: x) (texts r)
   | _ -> None)

(** val group_items : split_opts -> val0 list -> val0 list r0 **)

let group_items o l =
  match o.sp_group with
  | Some n0 ->
    ((fun fO fS n -> if n=0 then fO () else fS (n-1))
       (fun _ -> Uns0 "SPL: group 0 not documented")
       (fun _ ->
       match texts l with
       | Some ts -> Ok0 (map (fun x -> VList x) (chunk_f (length ts) n0 ts))
       | None ->
         Uns0
           "SPL: group of items that are not all Strings (List element kinds) not modelled")
       n0)
  | None -> Ok0 l

(** val sub_of : exchange -> val0 -> exchange **)

let sub_of x v =
  { x_msg = { m_body = v; m_headers = x.x_msg.m_headers }; x_props =
    x.x_props; x_vars = x.x_vars; x_mep = x.x_mep; x_exn = None; x_stop =
    false; x_eh = x.x_eh; x_seen = false; x_done = false; x_uow = []; x_orig =
    (Some { m_body = v; m_headers = x.x_msg.m_headers }) }

(** val cee : exn -> exn **)

let cee e =
  mkExn (str "org.apache.camel.CamelExchangeException") (str "?") (Some e)

(** val has_maxfail : split_opts -> bool **)

let has_maxfail o =
  match o.sp_maxfail with
  | Some _ -> true
  | None -> false

(** val copy_of : exchange -> exchange **)

let copy_of x =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = None; x_stop = false; x_eh = x.x_eh; x_seen = false; x_done =
    false; x_uow = []; x_orig = (Some x.x_msg) }

(** val kvin : chars -> val0 -> (chars * val0) list -> bool **)

let kvin k v l =
  existsb (fun pat -> let (k', v') = pat in (&&) (ceqs k k') (veqb v v')) l

(** val kvset_eqb : (chars * val0) list -> (chars * val0) list -> bool **)

let kvset_eqb a b =
  (&&) ((=) (length a) (length b))
    (forallb (fun pat -> let (k, v) = pat in kvin k v b) a)

(** val last_of : exchange list -> exchange option **)

let rec last_of = function
| [] -> None
| y :: r -> (match r with
             | [] -> Some y
             | _ :: _ -> last_of r)

(** val strat_result :
    bool -> strat -> exchange -> exchange list -> exchange option **)

let strat_result split st x acc =
  let same_props = forallb (fun y -> kvset_eqb y.x_props x.x_props) acc in
  let same_hdrs =
    forallb (fun y -> kvset_eqb y.x_msg.m_headers x.x_msg.m_headers) acc
  in
  (match st with
   | StNone ->
     if split
     then Some x
     else (match last_of acc with
           | Some y -> if same_props then Some (with_msg x y.x_msg) else None
           | None -> None)
   | StLatest ->
     (match last_of acc with
      | Some y -> if same_props then Some (with_msg x y.x_msg) else None
      | None -> None)
   | StOriginal -> Some x
   | StGroupedBody ->
     (match acc with
      | [] -> None
      | e :: l ->
        (match texts (map (fun y -> y.x_msg.m_body) (e :: l)) with
         | Some ts ->
           if (&&) same_props same_hdrs
           then Some (set_body x (VList ts))
           else None
         | None -> None)))

(** val agget : chars -> (chars * agroup) list -> agroup option **)

let rec agget k = function
| [] -> None
| p :: r -> let (k', a) = p in if ceqs k k' then Some a else agget k r

(** val agput :
    chars -> agroup -> (chars * agroup) list -> (chars * agroup) list **)

let rec agput k a = function
| [] -> (k, a) :: []
| p :: r ->
  let (k', a') = p in
  if ceqs k k' then (k', a) :: r else (k', a') :: (agput k a r)

(** val agdel : chars -> (chars * agroup) list -> (chars * agroup) list **)

let rec agdel k = function
| [] -> []
| p :: r ->
  let (k', a') = p in if ceqs k k' then agdel k r else (k', a') :: (agdel k r)

(** val aglget :
    chars -> (chars * (chars * agroup) list) list -> (chars * agroup) list **)

let rec aglget k = function
| [] -> []
| p :: r -> let (k', v) = p in if ceqs k k' then v else aglget k r

(** val aglset :
    chars -> (chars * agroup) list -> (chars * (chars * agroup) list) list ->
    (chars * (chars * agroup) list) list **)

let rec aglset k v = function
| [] -> (k, v) :: []
| p :: r ->
  let (k', v') = p in
  if ceqs k k' then (k', v) :: r else (k', v') :: (aglset k v r)

(** val clget : chars -> (chars * chars list) list -> chars list **)

let rec clget k = function
| [] -> []
| p :: r -> let (k', v) = p in if ceqs k k' then v else clget k r

(** val clset :
    chars -> chars list -> (chars * chars list) list -> (chars * chars list)
    list **)

let rec clset k v = function
| [] -> (k, v) :: []
| p :: r ->
  let (k', v') = p in
  if ceqs k k' then (k', v) :: r else (k', v') :: (clset k v r)

(** val with_groups :
    gstate -> chars -> ((chars * agroup) list -> (chars * agroup) list) ->
    gstate **)

let with_groups g id f =
  { g_global = g.g_global; g_route = g.g_route; g_group = g.g_group; g_agg =
    (aglset id (f (aglget id g.g_agg)) g.g_agg); g_closed = g.g_closed;
    g_cnt = g.g_cnt }

(** val close_key : gstate -> chars -> chars -> gstate **)

let close_key g id k =
  { g_global = g.g_global; g_route = g.g_route; g_group = g.g_group; g_agg =
    g.g_agg; g_closed = (clset id (k :: (clget id g.g_closed)) g.g_closed);
    g_cnt = g.g_cnt }

(** val is_closed : gstate -> chars -> chars -> bool **)

let is_closed g id k =
  existsb (ceqs k) (clget id g.g_closed)

(** val fresh : exchange -> exchange **)

let fresh x =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = None; x_stop = false; x_eh = true; x_seen = false; x_done = false;
    x_uow = []; x_orig = None }

(** val sdt : step -> bool **)

let rec sdt s1 =
  let l = let rec l = function
          | [] -> false
          | x :: r -> (||) (sdt x) (l r)
          in l
  in
  let lw =
    let rec lw = function
    | [] -> false
    | p :: r -> let (_, b) = p in (||) (l b) (lw r)
    in lw
  in
  (match s1 with
   | SFilter (_, b) -> l b
   | SChoice (ws, o) ->
     (||) (lw ws) (match o with
                   | Some b -> l b
                   | None -> false)
   | SPipeline b -> l b
   | STo ep -> (match ep with
                | EDirect _ -> true
                | EMock _ -> false)
   | SDoTry (_, _, _) -> true
   | SSplit (_, _, b) -> l b
   | SMulticast (_, b) -> l b
   | SAggregate (_, b) -> l b
   | SLoop (_, _, _, b) -> l b
   | SIdem (_, _, _, _, b) -> l b
   | SLB (_, _, b) -> l b
   | _ -> false)

(** val lsdt : step list -> bool **)

let lsdt ss =
  existsb sdt ss

type agres =
| AgCont of gstate
| AgEmit of gstate * exchange
| AgFail of exn
| AgUns of string

(** val same_as_first : exchange list -> bool **)

let same_as_first = function
| [] -> true
| y :: r ->
  forallb (fun z0 ->
    (&&) (kvset_eqb z0.x_msg.m_headers y.x_msg.m_headers)
      (kvset_eqb z0.x_props y.x_props))
    r

(** val agg_step : exchange -> gstate -> agg_opts -> agres **)

let agg_step x g o =
  match o.ago_strat with
  | StNone ->
    AgUns
      "AGG: no aggregation strategy (mandatory; refused at route creation) not modelled"
  | StLatest ->
    let st = StLatest in
    (match o.ago_size with
     | Some _ ->
       (match eval_expr x o.ago_corr with
        | EV v ->
          (match v with
           | VNull ->
             AgFail
               (mkExn (str "org.apache.camel.CamelExchangeException")
                 (str "?") None)
           | VStr s1 ->
             (match text_of (VStr s1) with
              | Some k ->
                if (&&) o.ago_close (is_closed g o.ago_id k)
                then AgFail
                       (mkExn
                         (str
                           "org.apache.camel.processor.aggregate.ClosedCorrelationKeyException")
                         (str "?") None)
                else let old = agget k (aglget o.ago_id g.g_agg) in
                     let n0 =
                       match old with
                       | Some a -> Stdlib.Int.succ a.ag_n
                       | None -> Stdlib.Int.succ 0
                     in
                     let ins =
                       app (match old with
                            | Some a -> a.ag_in
                            | None -> [])
                         (x :: [])
                     in
                     let agx =
                       match st with
                       | StGroupedBody ->
                         (match texts (map (fun y -> y.x_msg.m_body) ins) with
                          | Some ts ->
                            (match ins with
                             | [] -> None
                             | y :: _ -> Some (set_body (fresh y) (VList ts)))
                          | None -> None)
                       | _ -> Some (fresh x)
                     in
                     (match agx with
                      | Some agx0 ->
                        if negb
                             (match st with
                              | StGroupedBody -> same_as_first ins
                              | _ -> true)
                        then AgUns
                               "AGG: groupedBody of exchanges with different headers/properties (which ones it keeps) not documented"
                        else let by_size =
                               match o.ago_size with
                               | Some s2 -> (<=) s2 n0
                               | None -> false
                             in
                             (match match o.ago_pred with
                                    | Some p ->
                                      eval_pred
                                        (if o.ago_eager then x else agx0) p
                                    | None -> PB false with
                              | PB by_pred ->
                                if (||) by_size by_pred
                                then let g1 = with_groups g o.ago_id (agdel k)
                                     in
                                     AgEmit
                                     ((if o.ago_close
                                       then close_key g1 o.ago_id k
                                       else g1),
                                     agx0)
                                else AgCont
                                       (with_groups g o.ago_id
                                         (agput k { ag_x = agx0; ag_n = n0;
                                           ag_in = ins }))
                              | PUns0 w -> AgUns w)
                      | None ->
                        AgUns
                          "AGG: groupedBody of bodies that are not all Strings not modelled")
              | None ->
                AgUns "AGG: correlation key that is a List not modelled")
           | VInt z0 ->
             (match text_of (VInt z0) with
              | Some k ->
                if (&&) o.ago_close (is_closed g o.ago_id k)
                then AgFail
                       (mkExn
                         (str
                           "org.apache.camel.processor.aggregate.ClosedCorrelationKeyException")
                         (str "?") None)
                else let old = agget k (aglget o.ago_id g.g_agg) in
                     let n0 =
                       match old with
                       | Some a -> Stdlib.Int.succ a.ag_n
                       | None -> Stdlib.Int.succ 0
                     in
                     let ins =
                       app (match old with
                            | Some a -> a.ag_in
                            | None -> [])
                         (x :: [])
                     in
                     let agx =
                       match st with
                       | StGroupedBody ->
                         (match texts (map (fun y -> y.x_msg.m_body) ins) with
                          | Some ts ->
                            (match ins with
                             | [] -> None
                             | y :: _ -> Some (set_body (fresh y) (VList ts)))
                          | None -> None)
                       | _ -> Some (fresh x)
                     in
                     (match agx with
                      | Some agx0 ->
                        if negb
                             (match st with
                              | StGroupedBody -> same_as_first ins
                              | _ -> true)
                        then AgUns
                               "AGG: groupedBody of exchanges with different headers/properties (which ones it keeps) not documented"
                        else let by_size =
                               match o.ago_size with
                               | Some s1 -> (<=) s1 n0
                               | None -> false
                             in
                             (match match o.ago_pred with
                                    | Some p ->
                                      eval_pred
                                        (if o.ago_eager then x else agx0) p
                                    | None -> PB false with
                              | PB by_pred ->
                                if (||) by_size by_pred
                                then let g1 = with_groups g o.ago_id (agdel k)
                                     in
                                     AgEmit
                                     ((if o.ago_close
                                       then close_key g1 o.ago_id k
                                       else g1),
                                     agx0)
                                else AgCont
                                       (with_groups g o.ago_id
                                         (agput k { ag_x = agx0; ag_n = n0;
                                           ag_in = ins }))
                              | PUns0 w -> AgUns w)
                      | None ->
                        AgUns
                          "AGG: groupedBody of bodies that are not all Strings not modelled")
              | None ->
                AgUns "AGG: correlation key that is a List not modelled")
           | VLong z0 ->
             (match text_of (VLong z0) with
              | Some k ->
                if (&&) o.ago_close (is_closed g o.ago_id k)
                then AgFail
                       (mkExn
                         (str
                           "org.apache.camel.processor.aggregate.ClosedCorrelationKeyException")
                         (str "?") None)
                else let old = agget k (aglget o.ago_id g.g_agg) in
                     let n0 =
                       match old with
                       | Some a -> Stdlib.Int.succ a.ag_n
                       | None -> Stdlib.Int.succ 0
                     in
                     let ins =
                       app (match old with
                            | Some a -> a.ag_in
                            | None -> [])
                         (x :: [])
                     in
                     let agx =
                       match st with
                       | StGroupedBody ->
                         (match texts (map (fun y -> y.x_msg.m_body) ins) with
                          | Some ts ->
                            (match ins with
                             | [] -> None
                             | y :: _ -> Some (set_body (fresh y) (VList ts)))
                          | None -> None)
                       | _ -> Some (fresh x)
                     in
                     (match agx with
                      | Some agx0 ->
                        if negb
                             (match st with
                              | StGroupedBody -> same_as_first ins
                              | _ -> true)
                        then AgUns
                               "AGG: groupedBody of exchanges with different headers/properties (which ones it keeps) not documented"
                        else let by_size =
                               match o.ago_size with
                               | Some s1 -> (<=) s1 n0
                               | None -> false
                             in
                             (match match o.ago_pred with
                                    | Some p ->
                                      eval_pred
                                        (if o.ago_eager then x else agx0) p
                                    | None -> PB false with
                              | PB by_pred ->
                                if (||) by_size by_pred
                                then let g1 = with_groups g o.ago_id (agdel k)
                                     in
                                     AgEmit
                                     ((if o.ago_close
                                       then close_key g1 o.ago_id k
                                       else g1),
                                     agx0)
