                          match old with
                          | Some a -> Stdlib.Int.succ a.ag_n
                          | None -> Stdlib.Int.succ 0
                        in
                        let ins =
                          app (match old with
                               | Some a -> a.ag_in
                               | None -> [])
                            (x :: [])
                        in
                        let agx =
                          match st with
                          | StGroupedBody ->
                            (match texts (map (fun y -> y.x_msg.m_body) ins) with
                             | Some ts ->
                               (match ins with
                                | [] -> None
                                | y :: _ ->
                                  Some (set_body (fresh y) (VList ts)))
                             | None -> None)
                          | _ -> Some (fresh x)
                        in
                        (match agx with
                         | Some agx0 ->
                           if negb
                                (match st with
                                 | StGroupedBody -> same_as_first ins
                                 | _ -> true)
                           then AgUns
                                  "AGG: groupedBody of exchanges with different headers/properties (which ones it keeps) not documented"
                           else let by_size =
                                  match o.ago_size with
                                  | Some s1 -> (<=) s1 n0
                                  | None -> false
                                in
                                (match match o.ago_pred with
                                       | Some p ->
                                         eval_pred
                                           (if o.ago_eager then x else agx0) p
                                       | None -> PB false with
                                 | PB by_pred ->
                                   if (||) by_size by_pred
                                   then let g1 =
                                          with_groups g o.ago_id (agdel k)
                                        in
                                        AgEmit
                                        ((if o.ago_close
                                          then close_key g1 o.ago_id k
                                          else g1),
                                        agx0)
                                   else AgCont
                                          (with_groups g o.ago_id
                                            (agput k { ag_x = agx0; ag_n = n0;
                                              ag_in = ins }))
                                 | PUns0 w -> AgUns w)
                         | None ->
                           AgUns
                             "AGG: groupedBody of bodies that are not all Strings not modelled")
                 | None ->
                   AgUns "AGG: correlation key that is a List not modelled"))
           | EUns w -> AgUns w)
        | None ->
          AgUns
            "AGG: no completion (mandatory; refused at route creation) not modelled"))

type lcount =
| LcN of int
| LcFail
| LcUns of string

(** val loop_count : val0 -> lcount **)

let loop_count v = match v with
| VNull -> LcUns "LOOP: a null loop count not documented"
| _ ->
  (match conv_of v TInteger with
   | KV v0 ->
     (match v0 with
      | VInt z0 ->
        if Z.ltb z0 Big_int_Z.zero_big_int
        then LcUns "LOOP: a negative loop count not documented"
        else LcN (Z.to_nat z0)
      | _ ->
        LcUns
          "LOOP: the loop count converts to something other than an Integer")
   | KCannot _ -> LcFail
   | KUns w -> LcUns w
   | _ ->
     LcUns "LOOP: the loop count converts to something other than an Integer")

(** val loop_copy : exchange -> exchange -> exchange **)

let loop_copy orig cur =
  let c = copy_of orig in
  { x_msg = c.x_msg; x_props = c.x_props; x_vars = c.x_vars; x_mep = c.x_mep;
  x_exn = c.x_exn; x_stop = c.x_stop; x_eh = c.x_eh; x_seen = c.x_seen;
  x_done = c.x_done; x_uow = cur.x_uow; x_orig = cur.x_orig }

(** val rce : exn **)

let rce =
  mkExn (str "org.apache.camel.TypeConversionException") (str "?") (Some
    (mkExn (str "java.lang.NumberFormatException") (str "?") None))

(** val add_key : gstate -> chars -> chars -> gstate **)

let add_key =
  close_key

(** val add_uow : exchange -> chars -> chars -> exchange **)

let add_uow x id k =
  { x_msg = x.x_msg; x_props = x.x_props; x_vars = x.x_vars; x_mep = x.x_mep;
    x_exn = x.x_exn; x_stop = x.x_stop; x_eh = x.x_eh; x_seen = x.x_seen;
    x_done = x.x_done; x_uow = ((id, k) :: x.x_uow); x_orig = x.x_orig }

(** val remove_key : gstate -> (chars * chars) -> gstate **)

let remove_key g = function
| (id, k) ->
  { g_global = g.g_global; g_route = g.g_route; g_group = g.g_group; g_agg =
    g.g_agg; g_closed =
    (clset id (filter (fun k' -> negb (ceqs k k')) (clget id g.g_closed))
      g.g_closed);
    g_cnt = g.g_cnt }

(** val complete_uow : bool -> gstate -> exchange -> gstate **)

let complete_uow _ g x =
  if (||) (match x.x_exn with
           | Some _ -> true
           | None -> false) x.x_done
  then fold_left remove_key x.x_uow g
  else g

(** val cntget : chars -> (chars * int) list -> int **)

let rec cntget k = function
| [] -> 0
| p :: r -> let (k', n0) = p in if ceqs k k' then n0 else cntget k r

(** val cntset : chars -> int -> (chars * int) list -> (chars * int) list **)

let rec cntset k n0 = function
| [] -> (k, n0) :: []
| p :: r ->
  let (k', m) = p in
  if ceqs k k' then (k', n0) :: r else (k', m) :: (cntset k n0 r)

(** val bump : gstate -> chars -> gstate **)

let bump g id =
  { g_global = g.g_global; g_route = g.g_route; g_group = g.g_group; g_agg =
    g.g_agg; g_closed = g.g_closed; g_cnt =
    (cntset id (Stdlib.Int.succ (cntget id g.g_cnt)) g.g_cnt) }

(** val same_state : exchange -> exchange -> bool **)

let same_state y x =
  (&&)
    ((&&)
      ((&&) (veqb y.x_msg.m_body x.x_msg.m_body)
        (kvset_eqb y.x_msg.m_headers x.x_msg.m_headers))
      (kvset_eqb y.x_props x.x_props))
    (kveqb y.x_vars x.x_vars)

(** val fo_attempts : int -> Big_int_Z.big_int -> int **)

let fo_attempts n0 maxf =
  if Z.ltb maxf Big_int_Z.zero_big_int
  then n0
  else Nat.min n0 (Stdlib.Int.succ (Z.to_nat maxf))

(** val fo_monitored : bool -> chars list -> exn -> bool r0 **)

let fo_monitored real exs e =
  match exs with
  | [] -> Ok0 true
  | _ :: _ ->
    let MkExnS (c, _, cause, sup) = e in
    (match cause with
     | Some _ -> Uns0 "FO: monitored exceptions and causes not documented"
     | None ->
       (match any_instance c exs with
        | Ok0 a ->
          if a
          then Ok0 true
          else if real then chain_instance sup exs else Ok0 false
        | Uns0 w -> Uns0 w))

(** val uri_of : chars -> endpoint option **)

let uri_of u =
  match strip (str "direct:") u with
  | Some n0 ->
    (match n0 with
     | [] ->
       (match strip (str "mock:") u with
        | Some n1 -> (match n1 with
                      | [] -> None
                      | _ :: _ -> Some (EMock n1))
        | None -> None)
     | _ :: _ -> Some (EDirect n0))
  | None ->
    (match strip (str "mock:") u with
     | Some n0 -> (match n0 with
                   | [] -> None
                   | _ :: _ -> Some (EMock n0))
     | None -> None)

(** val uris_of : chars list -> endpoint list r0 **)

let rec uris_of = function
| [] -> Ok0 []
| u :: r ->
  (match uri_of u with
   | Some e ->
     (match uris_of r with
      | Ok0 es -> Ok0 (e :: es)
      | Uns0 w -> Uns0 w)
   | None ->
     Uns0
       "RLE: recipient URI other than direct:/mock: (or empty) not modelled")

(** val recipients : chars -> val0 -> endpoint list r0 **)

let recipients delim = function
| VStr s1 ->
  (match delim with
   | [] ->
     if ceqs delim (str "false")
     then uris_of (s1 :: [])
     else Uns0 "RLE: delimiter of several characters not modelled"
   | d :: l ->
     (match l with
      | [] -> uris_of (split_on d s1)
      | _ :: _ ->
        if ceqs delim (str "false")
        then uris_of (s1 :: [])
        else Uns0 "RLE: delimiter of several characters not modelled"))
| VList l -> uris_of l
| _ ->
  Uns0
    "RLE: recipient expression result other than String or List not modelled"

(** val slip_of : chars -> val0 -> endpoint list r0 **)

let slip_of delim v = match v with
| VNull -> Uns0 "RS: a null slip not documented"
| VStr s1 -> (match s1 with
              | [] -> Ok0 []
              | _ :: _ -> recipients delim v)
| VList l -> (match l with
              | [] -> Ok0 []
              | _ :: _ -> recipients delim v)
| _ -> recipients delim v

(** val any_exn : exn **)

let any_exn =
  mkExn (str "?") (str "?") None

type cbres =
| CbBody of val0
| CbFail
| CbUns of string

(** val convert_body : jtype -> bool -> val0 -> cbres **)

let convert_body t mandatory v =
  match conv_of v t with
  | KV w -> CbBody w
  | KDec _ -> CbUns "CB: a BigDecimal body is not a modelled value"
  | KNull ->
    if mandatory
    then CbUns "CB: mandatory conversion of null: outcome not documented (L0)"
    else CbBody VNull
  | KCannot _ ->
    if mandatory
    then CbFail
    else CbUns
           "CB: convertTo of a value that cannot be converted: null or TypeConversionException (L0)"
  | KUns w -> CbUns w

(** val keep_pending : exn -> exchange -> exchange **)

let keep_pending e x' =
  set_exn x' (Some
    (match x'.x_exn with
     | Some e2 -> add_suppressed e e2
     | None -> e))

(** val keep : exn option -> exchange -> exchange **)

let keep p x =
  match p with
  | Some e -> set_exn x (Some e)
  | None -> x

(** val halted : exchange -> bool **)

let halted x =
  (||) ((||) x.x_stop x.x_done)
    (match x.x_exn with
     | Some _ -> true
     | None -> false)

(** val merge_props :
    (chars * val0) list -> (chars * val0) list -> (chars * val0) list **)

let merge_props base over =
  fold_left (fun acc pat -> let (k, v) = pat in pset k v acc) over base

(** val is_dlc : ehconf -> bool **)

let is_dlc = function
| EHDefault -> false
| EHDlc (_, _, _) -> true

(** val dist_f : int -> chars -> chars -> int option r0 **)

let rec dist_f fuel c t =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> Uns0 "L0: class hierarchy deeper than the table")
    (fun f ->
    if ceqs c t
    then (match jdk_super t with
          | Some _ -> Ok0 (Some 0)
          | None -> Uns0 "L0: exception class outside the table")
    else (match jdk_super c with
          | Some o ->
            (match o with
             | Some p ->
               (match dist_f f p t with
                | Ok0 d -> Ok0 (option_map (fun x -> Stdlib.Int.succ x) d)
                | Uns0 w -> Uns0 w)
             | None ->
               (match jdk_super t with
                | Some _ -> Ok0 None
                | None -> Uns0 "L0: exception class outside the table"))
          | None -> Uns0 "L0: exception class outside the table"))
    fuel

(** val lt2 : (int * int) -> (int * int) -> bool **)

let lt2 a b =
  (||) (Nat.ltb (fst a) (fst b))
    ((&&) ((=) (fst a) (fst b)) (Nat.ltb (snd a) (snd b)))

(** val eq2 : (int * int) -> (int * int) -> bool **)

let eq2 a b =
  (&&) ((=) (fst a) (fst b)) ((=) (snd a) (snd b))

(** val best :
    (int * int) option -> (int * int) option -> (int * int) option **)

let best a b =
  match a with
  | Some p ->
    (match b with
     | Some q -> Some (if lt2 q p then q else p)
     | None -> Some p)
  | None -> b

(** val score_cls : chars -> int -> chars list -> (int * int) option r0 **)

let rec score_cls c i = function
| [] -> Ok0 None
| t :: r ->
  (match dist_f (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
           (Stdlib.Int.succ 0)))))))))))))))))))) c t with
   | Ok0 d ->
     (match score_cls c i r with
      | Ok0 b -> Ok0 (best (option_map (fun d0 -> (d0, i)) d) b)
      | Uns0 w -> Uns0 w)
   | Uns0 w -> Uns0 w)

(** val score_chain :
    exn list -> int -> chars list -> (int * int) option r0 **)

let rec score_chain es i ts =
  match es with
  | [] -> Ok0 None
  | e :: r ->
    (match score_cls (exn_class e) i ts with
     | Ok0 a ->
       (match score_chain r (Stdlib.Int.succ i) ts with
        | Ok0 b -> Ok0 (best a b)
        | Uns0 w -> Uns0 w)
     | Uns0 w -> Uns0 w)

(** val candidates :
    exchange -> exn -> clause list -> (((int * int) * bool) * clause) list r0 **)

let rec candidates x e = function
| [] -> Ok0 []
| k :: r ->
  (match score_chain (exn_chain e) 0 k.c_ex with
   | Ok0 a ->
     (match a with
      | Some sc ->
        (match candidates x e r with
         | Ok0 l ->
           (match k.c_when with
            | Some p ->
              (match eval_pred x p with
               | PB b -> if b then Ok0 (((sc, true), k) :: l) else Ok0 l
               | PUns0 w -> Uns0 w)
            | None -> Ok0 (((sc, false), k) :: l))
         | Uns0 w -> Uns0 w)
      | None -> candidates x e r)
   | Uns0 w -> Uns0 w)

(** val min_score :
    (((int * int) * bool) * clause) list -> (int * int) option **)

let rec min_score = function
| [] -> None
| p :: r ->
  let (p0, _) = p in let (sc, _) = p0 in best (Some sc) (min_score r)

(** val select_clause : clause list -> exchange -> exn -> clause option r0 **)

let select_clause c x e =
  match candidates x e c with
  | Ok0 l ->
    (match min_score l with
     | Some m ->
       let tied =
         filter (fun pat -> let (y, _) = pat in let (sc, _) = y in eq2 sc m) l
       in
       (match tied with
        | [] ->
          if existsb (fun pat -> let (y, _) = pat in let (_, w) = y in w) tied
          then Uns0 "EC: equally close onException clauses with onWhen"
          else (match rev tied with
                | [] -> Ok0 None
                | p :: _ -> let (_, k) = p in Ok0 (Some k))
        | p :: l0 ->
          let (_, k) = p in
          (match l0 with
           | [] -> Ok0 (Some k)
           | _ :: _ ->
             if existsb (fun pat -> let (y, _) = pat in let (_, w) = y in w)
                  tied
             then Uns0 "EC: equally close onException clauses with onWhen"
             else (match rev tied with
                   | [] -> Ok0 None
                   | p0 :: _ -> let (_, k0) = p0 in Ok0 (Some k0))))
     | None -> Ok0 None)
  | Uns0 w -> Uns0 w

(** val clause_matches : clause list -> ehconf -> exchange -> bool **)

let clause_matches c eHc x =
  match x.x_exn with
  | Some e ->
    (match select_clause c x e with
     | Ok0 a -> (match a with
                 | Some _ -> true
                 | None -> is_dlc eHc)
     | Uns0 _ -> true)
  | None -> false

(** val redelivery_headers : int -> exchange -> exchange **)

let redelivery_headers n0 x =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ -> x)
    (fun _ ->
    map_headers (fun hs ->
      hset (str "CamelRedeliveryMaxCounter") (VInt (Z.of_nat n0))
        (hset (str "CamelRedeliveryCounter") (VInt (Z.of_nat n0))
          (hset (str "CamelRedelivered") (VBool true) hs)))
      x)
    n0

(** val drop_redelivery_headers : exchange -> exchange **)

let drop_redelivery_headers x =
  map_headers (fun hs ->
    hremove (str "CamelRedeliveryMaxCounter")
      (hremove (str "CamelRedeliveryCounter")
        (hremove (str "CamelRedelivered") hs)))
    x

(** val not_redelivered_headers : int -> exchange -> exchange **)

let not_redelivered_headers n0 x =
  (fun fO fS n -> if n=0 then fO () else fS (n-1))
    (fun _ ->
    map_headers (fun hs ->
      hset (str "CamelRedeliveryCounter") (VInt Big_int_Z.zero_big_int)
        (hset (str "CamelRedelivered") (VBool false) hs))
      x)
    (fun _ -> x)
    n0

(** val eh_outcome :
    clause -> exchange -> exn -> exchange -> exchange option **)

let eh_outcome k x e y =
  if k.c_continued
  then (match k.c_handled with
        | Some b ->
          if b then None else Some (drop_redelivery_headers (set_eh y x.x_eh))
        | None -> Some (drop_redelivery_headers (set_eh y x.x_eh)))
  else (match k.c_handled with
        | Some b ->
          if b
          then Some
                 (drop_redelivery_headers (set_done (set_eh y x.x_eh) true))
          else Some
                 (set_seen
                   (set_exn
                     (not_redelivered_headers k.c_redeliveries
                       (set_eh y x.x_eh))
                     (Some e))
                   true)
        | None ->
          Some
            (set_seen
              (set_exn
                (not_redelivered_headers k.c_redeliveries (set_eh y x.x_eh))
                (Some e))
              true))

(** val block_input : clause -> exchange -> exchange **)

let block_input k x =
  if (||) k.c_continued (match k.c_handled with
                         | Some b -> b
                         | None -> false)
  then x
  else ((fun fO fS n -> if n=0 then fO () else fS (n-1))
          (fun _ -> not_redelivered_headers 0 x)
          (fun n0 ->
          redelivery_headers (Stdlib.Int.succ n0) x)
          k.c_redeliveries)

(** val surface : exchange -> exchange **)

let surface x =
  match x.x_exn with
  | Some _ -> if x.x_eh then set_seen x true else x
  | None -> x

(** val default_failed : clause list -> exchange -> exn -> exchange **)

let default_failed c x e =
  let x1 = set_seen (set_exn x (Some e)) x.x_eh in
  if (&&) x.x_eh (match c with
                  | [] -> false
                  | _ :: _ -> true)
  then not_redelivered_headers 0 x1
  else x1

(** val dlc_msg : uomode -> exchange -> message option **)

let dlc_msg uo x =
  match uo with
  | UONone -> Some x.x_msg
  | UOMessage -> x.x_orig
  | UOBody ->
    option_map (fun o -> { m_body = o.m_body; m_headers = x.x_msg.m_headers })
      x.x_orig

(** val dlc_out : uomode -> exchange -> exchange option **)

let dlc_out uo x =
  option_map (fun m ->
    drop_redelivery_headers (set_done (with_msg (set_exn x None) m) true))
    (dlc_msg uo x)

(** val dlc_fail :
    clause list -> ehconf -> exchange -> exn -> (exchange * event list) option **)

let dlc_fail c eHc x e =
  if x.x_eh
  then (match select_clause c (set_exn x (Some e)) e with
        | Ok0 a ->
          (match a with
           | Some _ -> None
           | None ->
             (match eHc with
              | EHDefault -> None
              | EHDlc (q, _, uo) ->
                option_map (fun x' -> (x', ((EvMock (q, x', false)) :: [])))
                  (dlc_out uo x)))
        | Uns0 _ -> None)
  else None

(** val dlc_takes : ehconf -> clause -> bool **)

let dlc_takes eHc k =
  (&&) (is_dlc eHc)
    (match k.c_steps with
     | [] -> negb k.c_continued
     | _ :: _ -> false)

(** val seen_if_failed : exchange -> exchange **)

let seen_if_failed x =
  match x.x_exn with
  | Some _ -> set_seen x true
  | None -> x

(** val abort_result : bool -> exchange -> exchange -> exn -> exchange **)

let abort_result real x y e =
  if real
  then set_exn
         (map_props (fun ps -> merge_props ps y.x_props) (with_msg x y.x_msg))
         (Some (cee e))
  else set_exn x (Some (cee e))

(** val find_route : route list -> chars -> route option **)

let find_route p n0 =
  find (fun r -> ceqs r.r_from n0) p

(** val oc_failed : exchange -> bool **)

let oc_failed x =
  match x.x_exn with
  | Some _ -> true
  | None -> false

(** val oc_trig_ok : octrig -> exchange -> bool **)

let oc_trig_ok k x =
  match k with
  | OcAlways -> true
  | OcComplete -> negb (oc_failed x)
  | OcFailure -> oc_failed x

(** val oc_fires : oncomp -> exchange -> pres0 **)

let oc_fires o x =
  if oc_trig_ok o.oc_trig x
  then (match o.oc_when with
        | Some p -> eval_pred x p
        | None -> PB true)
  else PB false

(** val oc_input : oncomp -> exchange -> exchange option **)

let oc_input o x =
  option_map (fun m ->
    set_eh
      (set_seen
        (set_done (set_stop (set_exn (with_msg x m) None) false) false) false)
      false)
    (if o.oc_orig then x.x_orig else Some x.x_msg)

type out =
| ODone of gstate * exchange * event list * string list
| OUns of string

(** val seqo :
    out -> (gstate -> exchange -> event list -> string list -> out) -> out **)

let seqo o k =
  match o with
  | ODone (g, x, t, h) -> k g x t h
  | OUns w -> OUns w

(** val tag : string -> out -> out **)

let tag r = function
| ODone (g, x, t, h) -> ODone (g, x, t, (r :: h))
| OUns w -> OUns w

(** val done1 : string -> gstate -> exchange -> out **)

let done1 r g x =
  ODone (g, x, [], (r :: []))

(** val run0 :
    route list -> bool -> clause list -> ehconf -> int -> gstate -> exchange
    -> step list -> out **)

let run0 p real c eHc =
  let rec run1 fuel g x ss =
    (fun fO fS n -> if n=0 then fO () else fS (n-1))
      (fun _ -> OUns "fuel")
      (fun f ->
      match ss with
      | [] -> done1 "L2.pipeline.nil" g x
      | s1 :: ss' ->
        if halted x
        then done1 "L2.pipeline.halt" g x
        else seqo (run2 f g x s1) (fun g1 x1 t1 h1 ->
               if (&&) ((&&) x1.x_eh (negb x1.x_seen))
                    (clause_matches c eHc x1)
               then OUns
                      "EH: a new exception at a composite step that an onException clause matches (retry/handling there not modelled)"
               else seqo (run1 f g1 (surface x1) ss') (fun g2 x2 t2 h2 ->
                      ODone (g2, x2, (app t1 t2),
                      ("L2.pipeline.seq" :: (app h1 h2))))))
      fuel
  and run2 fuel g x s1 =
    (fun fO fS n -> if n=0 then fO () else fS (n-1))
      (fun _ -> OUns "fuel")
      (fun f ->
      match s1 with
      | SSetBody e ->
        (match eval_expr x e with
         | EV v -> done1 "L2.setBody" g (set_body x v)
         | EUns w -> OUns w)
      | STransform e ->
        (match eval_expr x e with
         | EV v -> done1 "L2.transform" g (set_body x v)
         | EUns w -> OUns w)
      | SSetHeader (k, e) ->
        if ascii_name k
        then (match eval_expr x e with
              | EV v -> done1 "L2.setHeader" g (map_headers (hset k v) x)
              | EUns w -> OUns w)
        else OUns "L0: header name outside printable ASCII"
