                 if x'.x_stop
                 then OUns
                        "DT: stop inside doFinally while an exception is pending"
                 else ODone (g', (keep_pending e x'), (unknown_exn t),
                        ("L3.doFinally.pending" :: h))
               | None ->
                 ODone (g', (set_done x' ((||) x.x_done x'.x_done)), t,
                   ("L3.doFinally.run" :: (if x.x_done
                                           then "L3.doFinally.after-complete" :: h
                                           else h))))
      | None -> done1 "L3.doTry.no-finally" g (keep p0 x))
      fuel
  and runch fuel g x ws o =
    (fun fO fS n -> if n=0 then fO () else fS (n-1))
      (fun _ -> OUns "fuel")
      (fun f ->
      match ws with
      | [] ->
        (match o with
         | Some ss -> tag "L2.choice.otherwise" (run1 f g x ss)
         | None -> done1 "L2.choice.none" g x)
      | p0 :: ws' ->
        let (p1, ss) = p0 in
        (match eval_pred x p1 with
         | PB b ->
           if b
           then tag "L2.choice.first-match" (run1 f g x ss)
           else runch f g x ws' o
         | PUns0 w -> OUns w))
      fuel
  in run1

(** val runoc :
    route list -> bool -> clause list -> ehconf -> int -> oncomp option ->
    gstate -> exchange -> out **)

let runoc p real c eHc fuel oc g x =
  match oc with
  | Some o ->
    (match oc_fires o x with
     | PB b ->
       if b
       then (match oc_input o x with
             | Some y0 ->
               if (&&) ((&&) ((&&) o.oc_before real) o.oc_orig)
                    (match x.x_mep with
                     | InOnly -> false
                     | InOut -> true)
               then OUns
                      "REAL: BeforeConsumer + useOriginalMessage on an InOut exchange sees the current message (finding)"
               else if (&&)
                         ((&&) ((&&) ((&&) (negb o.oc_before) real) o.oc_orig)
                           x.x_done)
                         (match eHc with
                          | EHDefault -> false
                          | EHDlc (_, _, uo) ->
                            (match uo with
                             | UOMessage -> true
                             | _ -> false))
                    then OUns
                           "REAL: the onCompletion copy shares the original message the dead letter channel put on the exchange (finding)"
                    else seqo (run0 p real c eHc fuel g y0 o.oc_steps)
                           (fun g' y t h ->
                           match y.x_exn with
                           | Some _ ->
                             OUns
                               "OC: an exception in the onCompletion steps (it does not interfere with the caller [OC.42-43]; not modelled)"
                           | None ->
                             if (||) y.x_stop y.x_done
                             then OUns
                                    "OC: a stop in the onCompletion steps not documented"
                             else if o.oc_before
                                  then if (&&) (kveqb y.x_vars y0.x_vars)
                                            (kvset_eqb y.x_props y0.x_props)
                                       then ODone (g', (with_msg x y.x_msg),
                                              t,
                                              ("L3.onCompletion" :: ("L3.onCompletion.trigger" :: ("L3.onCompletion.before" :: h))))
                                       else OUns
                                              "OC: BeforeConsumer steps that change properties or variables: not documented"
                                  else ODone (g', x, t,
                                         ("L3.onCompletion" :: ("L3.onCompletion.trigger" :: h))))
             | None ->
               OUns
                 "OC: the original message of an aggregator's output is not documented")
       else ODone (g, x, [],
              ("L3.onCompletion" :: ("L3.onCompletion.trigger" :: [])))
     | PUns0 w -> OUns w)
  | None -> ODone (g, x, [], [])

type send = { s_to : chars; s_mep : mep; s_body : val0;
              s_headers : (chars * val0) list }

type sres =
| SDone of event list * exchange * string list
| SUns of string

(** val clause_unconfigured : clause -> bool **)

let clause_unconfigured k =
  match k.c_steps with
  | [] ->
    (match k.c_handled with
     | Some _ -> false
     | None ->
       if k.c_continued
       then false
       else ((fun fO fS n -> if n=0 then fO () else fS (n-1))
               (fun _ -> true)
               (fun _ -> false)
               k.c_redeliveries))
  | _ :: _ -> false

(** val run_case_ :
    bool -> clause list -> ehconf -> oncomp option -> int -> route list ->
    gstate -> send list -> sres list * gstate **)

let rec run_case_ real c e oC fuel p g = function
| [] -> ([], g)
| s1 :: ss' ->
  (match find_route p s1.s_to with
   | Some r ->
     (match run0 p real c e fuel g
              (new_exchange s1.s_mep s1.s_body s1.s_headers) r.r_steps with
      | ODone (g', x, t, h) ->
        let oc =
          match p with
          | [] -> None
          | r1 :: _ -> if ceqs r1.r_from s1.s_to then oC else None
        in
        (match runoc p real c e fuel oc g' x with
         | ODone (g2, x2, t2, h2) ->
           let (rs, g'') =
             run_case_ real c e oC fuel p (complete_uow real g2 x2) ss'
           in
           (((SDone ((app t t2), x2, (app h h2))) :: rs), g'')
         | OUns w -> (((SUns w) :: []), g))
      | OUns w -> (((SUns w) :: []), g))
   | None -> (((SUns "DC: send to direct: without a consumer") :: []), g))

(** val run_case :
    bool -> clause list -> ehconf -> oncomp option -> int -> route list ->
    gstate -> send list -> sres list * gstate **)

let run_case real c e oC fuel p g ss =
  if existsb clause_unconfigured c
  then (((SUns
         "EC: onException without steps or options (refused at route creation; not documented)") :: []),
         g)
  else (match oC with
        | Some o ->
          (match o.oc_steps with
           | [] ->
             (((SUns
               "OC: onCompletion without steps (refused at route creation: no children; not documented)") :: []),
               g)
           | _ :: _ -> run_case_ real c e oC fuel p g ss)
        | None -> run_case_ real c e oC fuel p g ss)

(** val s : string -> chars **)

let s =
  str

(** val xesc : chars -> chars **)

let rec xesc = function
| [] -> []
| c :: r ->
  app
    (if ceq c '&'
     then s "&amp;"
     else if ceq c '<'
          then s "&lt;"
          else if ceq c '>'
               then s "&gt;"
               else if ceq c
                         (ascii_of_nat (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ
                           0)))))))))))))))))))))))))))))))))))
                    then s "&quot;"
                    else if ceq c '\'' then s "&apos;" else c :: [])
    (xesc r)

(** val attr : string -> chars -> chars **)

let attr k v =
  app (s " ") (app (s k) (app (s "=\"") (app (xesc v) (s "\""))))

(** val elem : string -> chars -> chars -> chars **)

let elem tag0 attrs body =
  app (s "<")
    (app (s tag0)
      (app attrs
        (app (s ">") (app body (app (s "</") (app (s tag0) (s ">")))))))

(** val empty : string -> chars -> chars **)

let empty tag0 attrs =
  app (s "<") (app (s tag0) (app attrs (s "/>")))

(** val btxt : bool -> chars **)

let btxt = function
| true -> s "true"
| false -> s "false"

(** val ntxt : int -> chars **)

let ntxt n0 =
  ztext (Z.of_nat n0)

(** val xexpr : expr -> chars **)

let xexpr = function
| XSimple p -> elem "simple" [] (xesc (render p))
| XLang e0 ->
  (match e0 with
   | XConstant (t, _, _) -> elem "constant" [] (xesc t)
   | XHeader (n0, _) -> elem "header" [] (xesc n0)
   | XProp (n0, _) -> elem "exchangeProperty" [] (xesc n0)
   | XVar (n0, _) -> elem "variable" [] (xesc n0)
   | _ -> s "<!-- not rendered -->")

(** val strat_attr : strat -> chars **)

let strat_attr = function
| StNone -> []
| StLatest ->
  attr "aggregationStrategy"
    (s
      "#class:org.apache.camel.processor.aggregate.UseLatestAggregationStrategy")
| StOriginal ->
  attr "aggregationStrategy"
    (s
      "#class:org.apache.camel.processor.aggregate.UseOriginalAggregationStrategy")
| StGroupedBody ->
  attr "aggregationStrategy"
    (s
      "#class:org.apache.camel.processor.aggregate.GroupedBodyAggregationStrategy")

(** val uri : endpoint -> chars **)

let uri = function
| EDirect n0 -> app (s "direct:") n0
| EMock n0 -> app (s "mock:") n0

(** val joinc : chars list -> chars **)

let rec joinc = function
| [] -> []
| x :: r -> (match r with
             | [] -> x
             | _ :: _ -> app x (app (s ",") (joinc r)))

(** val xstep : step -> chars **)

let rec xstep st =
  let xsteps0 =
    let rec xsteps0 = function
    | [] -> []
    | x :: r -> app (xstep x) (xsteps0 r)
    in xsteps0
  in
  let xwhens =
    let rec xwhens = function
    | [] -> []
    | p0 :: r ->
      let (p, b) = p0 in
      app (elem "when" [] (app (xexpr p) (xsteps0 b))) (xwhens r)
    in xwhens
  in
  let xcatches =
    let rec xcatches = function
    | [] -> []
    | p :: r ->
      let (p0, b) = p in
      let (ts, w) = p0 in
      app
        (elem "doCatch" []
          (app
            (concat_with [] (map (fun t -> elem "exception" [] (xesc t)) ts))
            (app
              (match w with
               | Some p1 -> elem "onWhen" [] (xexpr p1)
               | None -> [])
              (xsteps0 b))))
        (xcatches r)
    in xcatches
  in
  (match st with
   | SSetBody e -> elem "setBody" [] (xexpr e)
   | STransform e -> elem "transform" [] (xexpr e)
   | SSetHeader (k, e) -> elem "setHeader" (attr "name" k) (xexpr e)
   | SSetProperty (k, e) -> elem "setProperty" (attr "name" k) (xexpr e)
   | SSetVariable (k, e) -> elem "setVariable" (attr "name" k) (xexpr e)
   | SRemoveHeader k -> empty "removeHeader" (attr "name" k)
   | SRemoveHeaders (p, xs) ->
     empty "removeHeaders"
       (app (attr "pattern" p)
         (match xs with
          | [] -> []
          | _ :: _ -> attr "excludePattern" (joinc xs)))
   | SRemoveProperty k -> empty "removeProperty" (attr "name" k)
   | SRemoveVariable k -> empty "removeVariable" (attr "name" k)
   | SFilter (p, b) -> elem "filter" [] (app (xexpr p) (xsteps0 b))
   | SChoice (ws, o) ->
     elem "choice" []
       (app (xwhens ws)
         (match o with
          | Some b -> elem "otherwise" [] (xsteps0 b)
          | None -> []))
   | SPipeline b -> elem "pipeline" [] (xsteps0 b)
   | STo ep -> empty "to" (attr "uri" (uri ep))
   | SStop -> empty "stop" []
   | SThrow (c, m) ->
     empty "throwException" (app (attr "exceptionType" c) (attr "message" m))
   | SDoTry (b, cs, f) ->
     elem "doTry" []
       (app (xsteps0 b)
         (app (xcatches cs)
           (match f with
            | Some fb -> elem "doFinally" [] (xsteps0 fb)
            | None -> [])))
   | SSplit (e, o, b) ->
     elem "split"
       (app (if o.sp_stop then attr "stopOnException" (s "true") else [])
         (app
           (match o.sp_group with
            | Some n0 -> attr "group" (ntxt n0)
            | None -> [])
           (app (attr "delimiter" o.sp_delim)
             (app
               (match o.sp_maxfail with
                | Some n0 -> attr "maxFailedRecords" (ntxt n0)
                | None -> [])
               (strat_attr o.sp_strat)))))
       (app (xexpr e) (xsteps0 b))
   | SMulticast (stg, b) -> elem "multicast" (strat_attr stg) (xsteps0 b)
   | SRecipientList (stg, e, d) ->
     elem "recipientList" (app (attr "delimiter" d) (strat_attr stg))
       (xexpr e)
   | SAggregate (o, b) ->
     elem "aggregate"
       (app (strat_attr o.ago_strat)
         (app
           (match o.ago_size with
            | Some n0 -> attr "completionSize" (ntxt n0)
            | None -> [])
           (app
             (if o.ago_eager
              then attr "eagerCheckCompletion" (s "true")
              else [])
             (app
               (if o.ago_close
                then attr "closeCorrelationKeyOnCompletion" (s "0")
                else [])
               (attr "executorService" (s "syncExec"))))))
       (app (elem "correlationExpression" [] (xexpr o.ago_corr))
         (app
           (match o.ago_pred with
            | Some p -> elem "completionPredicate" [] (xexpr p)
            | None -> [])
           (xsteps0 b)))
   | SLoop (e, cp, dw, b) ->
     elem "loop"
       (app (if cp then attr "copy" (s "true") else [])
         (if dw then attr "doWhile" (s "true") else []))
       (app (xexpr e) (xsteps0 b))
   | SIdem (_, e, sk, eg, b) ->
     elem "idempotentConsumer"
       (app
         (attr "idempotentRepository"
           (s
             "#class:org.apache.camel.support.processor.idempotent.MemoryIdempotentRepository"))
         (app (attr "skipDuplicate" (btxt sk)) (attr "eager" (btxt eg))))
       (app (xexpr e) (xsteps0 b))
   | SLB (_, k, b) ->
     (match k with
      | LBRoundRobin ->
        elem "loadBalance" []
          (app (empty "roundRobinLoadBalancer" []) (xsteps0 b))
      | LBFailover (exs, mx) ->
        elem "loadBalance" []
          (app
            (elem "failoverLoadBalancer"
              (attr "maximumFailoverAttempts" (ztext mx))
              (concat_with []
                (map (fun t -> elem "exception" [] (xesc t)) exs)))
            (xsteps0 b)))
   | SRoutingSlip (e, d) ->
     elem "routingSlip" (attr "uriDelimiter" d) (xexpr e)
   | SDynamicRouter (e, d) ->
     elem "dynamicRouter" (attr "uriDelimiter" d) (xexpr e)
   | SConvertBody (t, m) ->
     empty "convertBodyTo"
       (app (attr "type" (str (jname t))) (attr "mandatory" (btxt m))))

(** val xsteps : step list -> chars **)

let xsteps l =
  concat_with [] (map xstep l)

(** val xclause : clause -> chars **)

let xclause k =
  elem "onException" []
    (app (concat_with [] (map (fun t -> elem "exception" [] (xesc t)) k.c_ex))
      (app
        (match k.c_when with
         | Some p -> elem "onWhen" [] (xexpr p)
         | None -> [])
        (app
          ((fun fO fS n -> if n=0 then fO () else fS (n-1))
             (fun _ -> [])
             (fun n0 ->
             empty "redeliveryPolicy"
               (app (attr "maximumRedeliveries" (ntxt (Stdlib.Int.succ n0)))
                 (attr "redeliveryDelay" (s "0"))))
             k.c_redeliveries)
          (app
            (match k.c_handled with
             | Some b -> elem "handled" [] (elem "constant" [] (btxt b))
             | None -> [])
            (app
              (if k.c_continued
               then elem "continued" [] (elem "constant" [] (s "true"))
               else [])
              (xsteps k.c_steps))))))

(** val xeh : ehconf -> chars **)

let xeh = function
| EHDefault -> []
| EHDlc (q, n0, uo) ->
  elem "errorHandler" []
    (elem "deadLetterChannel"
      (app (attr "deadLetterUri" (app (s "mock:") q))
        (match uo with
         | UONone -> []
         | UOMessage -> attr "useOriginalMessage" (s "true")
         | UOBody -> attr "useOriginalBody" (s "true")))
      (empty "redeliveryPolicy"
        (app (attr "maximumRedeliveries" (ntxt n0))
          (attr "redeliveryDelay" (s "0")))))

(** val xoc : oncomp -> chars **)

let xoc o =
  elem "onCompletion"
    (app
      (match o.oc_trig with
       | OcAlways -> []
       | OcComplete -> attr "onCompleteOnly" (s "true")
       | OcFailure -> attr "onFailureOnly" (s "true"))
      (app (if o.oc_before then attr "mode" (s "BeforeConsumer") else [])
        (if o.oc_orig then attr "useOriginalMessage" (s "true") else [])))
    (app
      (match o.oc_when with
       | Some p -> elem "onWhen" [] (xexpr p)
       | None -> [])
      (xsteps o.oc_steps))

(** val xroute : clause list -> ehconf -> oncomp option -> route -> chars **)

let xroute c e oc r =
  elem "route" (attr "id" r.r_id)
    (app (xeh e)
      (app (empty "from" (attr "uri" (app (s "direct:") r.r_from)))
        (app (match oc with
              | Some o -> xoc o
              | None -> [])
          (app (concat_with [] (map xclause c)) (xsteps r.r_steps)))))

(** val xml_program :
    clause list -> ehconf -> oncomp option -> route list -> chars **)

let xml_program c e oC p =
  elem "routes" (attr "xmlns" (s "http://camel.apache.org/schema/xml-io"))
    (concat_with []
      (match p with
       | [] -> []
       | r1 :: rs -> (xroute c e oC r1) :: (map (xroute c e None) rs)))

