           0)))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))
           n0)

(** val jesc : chars -> chars **)

let rec jesc = function
| [] -> []
| c :: r ->
  let n0 = nat_of_ascii c in
  app
    (if ceq c dq0
     then bsl0 :: (dq0 :: [])
     else if ceq c bsl0
          then bsl0 :: (bsl0 :: [])
          else if Nat.ltb n0 (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                    0))))))))))))))))))))))))))))))))
               then app (s0 "\\u00")
                      ((hex1
                         (Nat.div n0 (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
                           (Stdlib.Int.succ (Stdlib.Int.succ
                           0)))))))))))))))))) :: ((hex1
                                                     (Nat.modulo n0
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
