                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       (Stdlib.Int.succ
                                                       0)))))))))))))))))) :: []))
               else c :: [])
    (jesc r)

(** val jstr : chars -> chars **)

let jstr t =
  app (dq0 :: []) (app (jesc t) (dq0 :: []))

(** val kv0 : string -> chars -> chars **)

let kv0 k v =
  app (jstr (s0 k)) (app (s0 ":") v)

(** val commas : chars list -> chars **)

let rec commas = function
| [] -> []
| x :: r -> (match r with
             | [] -> x
             | _ :: _ -> app x (app (s0 ",") (commas r)))

(** val obj : chars list -> chars **)

let obj fields =
  app (s0 "{") (app (commas fields) (s0 "}"))

(** val arr : chars list -> chars **)

let arr items =
  app (s0 "[") (app (commas items) (s0 "]"))

(** val btxt0 : bool -> chars **)

let btxt0 = function
| true -> s0 "true"
| false -> s0 "false"

(** val ntxt0 : int -> chars **)

let ntxt0 n0 =
  ztext (Z.of_nat n0)

(** val yexpr : expr -> chars **)

let yexpr = function
| XSimple p -> obj ((kv0 "simple" (jstr (render p))) :: [])
| XLang e0 ->
  (match e0 with
   | XConstant (t, _, _) -> obj ((kv0 "constant" (jstr t)) :: [])
   | XHeader (n0, _) -> obj ((kv0 "header" (jstr n0)) :: [])
   | XProp (n0, _) -> obj ((kv0 "exchangeProperty" (jstr n0)) :: [])
   | XVar (n0, _) -> obj ((kv0 "variable" (jstr n0)) :: [])
   | _ -> obj [])

(** val exprf : expr -> chars **)

let exprf e =
  kv0 "expression" (yexpr e)

(** val strat_f : strat -> chars list **)

let strat_f = function
| StNone -> []
| StLatest ->
  (kv0 "aggregationStrategy"
    (jstr
      (s0
        "#class:org.apache.camel.processor.aggregate.UseLatestAggregationStrategy"))) :: []
| StOriginal ->
  (kv0 "aggregationStrategy"
    (jstr
      (s0
        "#class:org.apache.camel.processor.aggregate.UseOriginalAggregationStrategy"))) :: []
| StGroupedBody ->
  (kv0 "aggregationStrategy"
    (jstr
      (s0
        "#class:org.apache.camel.processor.aggregate.GroupedBodyAggregationStrategy"))) :: []

(** val uri0 : endpoint -> chars **)

let uri0 = function
| EDirect n0 -> app (s0 "direct:") n0
| EMock n0 -> app (s0 "mock:") n0

(** val joinc0 : chars list -> chars **)

let rec joinc0 = function
| [] -> []
| x :: r -> (match r with
             | [] -> x
             | _ :: _ -> app x (app (s0 ",") (joinc0 r)))

(** val step1 : string -> chars list -> chars **)

let step1 name fields =
  obj ((kv0 name (obj fields)) :: [])

(** val ystep : step -> chars **)

let rec ystep st =
  let ysteps0 =
    let rec ysteps0 = function
    | [] -> []
    | x :: r -> (ystep x) :: (ysteps0 r)
    in ysteps0
  in
  let stepsf = fun l -> kv0 "steps" (arr (ysteps0 l)) in
  let ywhens =
    let rec ywhens = function
    | [] -> []
    | p0 :: r ->
      let (p, b) = p0 in (obj ((exprf p) :: ((stepsf b) :: []))) :: (ywhens r)
    in ywhens
  in
  let ycatches =
    let rec ycatches = function
    | [] -> []
    | p :: r ->
      let (p0, b) = p in
      let (ts, w) = p0 in
      (obj
        (app ((kv0 "exception" (arr (map jstr ts))) :: [])
          (app
            (match w with
             | Some p1 -> (kv0 "onWhen" (obj ((exprf p1) :: []))) :: []
             | None -> [])
            ((stepsf b) :: [])))) :: (ycatches r)
    in ycatches
  in
  (match st with
   | SSetBody e -> step1 "setBody" ((exprf e) :: [])
   | STransform e -> step1 "transform" ((exprf e) :: [])
   | SSetHeader (k, e) ->
     step1 "setHeader" ((kv0 "name" (jstr k)) :: ((exprf e) :: []))
   | SSetProperty (k, e) ->
     step1 "setProperty" ((kv0 "name" (jstr k)) :: ((exprf e) :: []))
   | SSetVariable (k, e) ->
     step1 "setVariable" ((kv0 "name" (jstr k)) :: ((exprf e) :: []))
   | SRemoveHeader k -> step1 "removeHeader" ((kv0 "name" (jstr k)) :: [])
   | SRemoveHeaders (p, xs) ->
     step1 "removeHeaders"
       (app ((kv0 "pattern" (jstr p)) :: [])
         (match xs with
          | [] -> []
          | _ :: _ -> (kv0 "excludePattern" (jstr (joinc0 xs))) :: []))
   | SRemoveProperty k -> step1 "removeProperty" ((kv0 "name" (jstr k)) :: [])
   | SRemoveVariable k -> step1 "removeVariable" ((kv0 "name" (jstr k)) :: [])
   | SFilter (p, b) -> step1 "filter" ((exprf p) :: ((stepsf b) :: []))
   | SChoice (ws, o) ->
     step1 "choice"
       (app ((kv0 "when" (arr (ywhens ws))) :: [])
         (match o with
          | Some b -> (kv0 "otherwise" (obj ((stepsf b) :: []))) :: []
          | None -> []))
   | SPipeline b -> step1 "pipeline" ((stepsf b) :: [])
   | STo ep -> step1 "to" ((kv0 "uri" (jstr (uri0 ep))) :: [])
   | SStop -> step1 "stop" []
   | SThrow (c, m) ->
     step1 "throwException"
       ((kv0 "exceptionType" (jstr c)) :: ((kv0 "message" (jstr m)) :: []))
   | SDoTry (b, cs, f) ->
     step1 "doTry"
       (app ((stepsf b) :: [])
         (app
           (match cs with
            | [] -> []
            | _ :: _ -> (kv0 "doCatch" (arr (ycatches cs))) :: [])
           (match f with
            | Some fb -> (kv0 "doFinally" (obj ((stepsf fb) :: []))) :: []
            | None -> [])))
   | SSplit (e, o, b) ->
     step1 "split"
       (app ((exprf e) :: [])
         (app
           (if o.sp_stop
            then (kv0 "stopOnException" (s0 "true")) :: []
            else [])
           (app
             (match o.sp_group with
              | Some n0 -> (kv0 "group" (ntxt0 n0)) :: []
              | None -> [])
             (app ((kv0 "delimiter" (jstr o.sp_delim)) :: [])
               (app
                 (match o.sp_maxfail with
                  | Some n0 -> (kv0 "maxFailedRecords" (ntxt0 n0)) :: []
                  | None -> [])
                 (app (strat_f o.sp_strat) ((stepsf b) :: [])))))))
   | SMulticast (stg, b) ->
     step1 "multicast" (app (strat_f stg) ((stepsf b) :: []))
   | SRecipientList (stg, e, d) ->
     step1 "recipientList"
       (app ((exprf e) :: ((kv0 "delimiter" (jstr d)) :: [])) (strat_f stg))
   | SAggregate (o, b) ->
     step1 "aggregate"
       (app ((kv0 "correlationExpression" (yexpr o.ago_corr)) :: [])
         (app
           (match o.ago_pred with
            | Some p -> (kv0 "completionPredicate" (yexpr p)) :: []
            | None -> [])
           (app (strat_f o.ago_strat)
             (app
               (match o.ago_size with
                | Some n0 -> (kv0 "completionSize" (ntxt0 n0)) :: []
                | None -> [])
               (app
                 (if o.ago_eager
                  then (kv0 "eagerCheckCompletion" (s0 "true")) :: []
                  else [])
                 (app
                   (if o.ago_close
                    then (kv0 "closeCorrelationKeyOnCompletion" (s0 "0")) :: []
                    else [])
                   ((kv0 "executorService" (jstr (s0 "syncExec"))) :: (
                   (stepsf b) :: []))))))))
   | SLoop (e, cp, dw, b) ->
     step1 "loop"
       (app ((exprf e) :: [])
         (app (if cp then (kv0 "copy" (s0 "true")) :: [] else [])
           (app (if dw then (kv0 "doWhile" (s0 "true")) :: [] else [])
             ((stepsf b) :: []))))
   | SIdem (_, e, sk, eg, b) ->
     step1 "idempotentConsumer"
       ((exprf e) :: ((kv0 "idempotentRepository"
                        (jstr
                          (s0
                            "#class:org.apache.camel.support.processor.idempotent.MemoryIdempotentRepository"))) :: (
       (kv0 "skipDuplicate" (btxt0 sk)) :: ((kv0 "eager" (btxt0 eg)) :: (
       (stepsf b) :: [])))))
   | SLB (_, k, b) ->
     (match k with
      | LBRoundRobin ->
        step1 "loadBalance"
          ((kv0 "roundRobinLoadBalancer" (obj [])) :: ((stepsf b) :: []))
      | LBFailover (exs, mx) ->
        step1 "loadBalance"
          ((kv0 "failoverLoadBalancer"
             (obj
               (app
                 (match exs with
                  | [] -> []
                  | _ :: _ -> (kv0 "exception" (arr (map jstr exs))) :: [])
                 ((kv0 "maximumFailoverAttempts" (jstr (ztext mx))) :: [])))) :: (
          (stepsf b) :: [])))
   | SRoutingSlip (e, d) ->
     step1 "routingSlip" ((exprf e) :: ((kv0 "uriDelimiter" (jstr d)) :: []))
   | SDynamicRouter (e, d) ->
     step1 "dynamicRouter"
       ((exprf e) :: ((kv0 "uriDelimiter" (jstr d)) :: []))
   | SConvertBody (t, m) ->
     step1 "convertBodyTo"
       ((kv0 "type" (jstr (str (jname t)))) :: ((kv0 "mandatory" (btxt0 m)) :: [])))

(** val ysteps : step list -> chars **)

let ysteps l =
  arr (map ystep l)

(** val yclause : clause -> chars **)

let yclause k =
  obj
    ((kv0 "onException"
       (obj
         (app ((kv0 "exception" (arr (map jstr k.c_ex))) :: [])
           (app
             (match k.c_when with
              | Some p -> (kv0 "onWhen" (obj ((exprf p) :: []))) :: []
              | None -> [])
             (app
               ((fun fO fS n -> if n=0 then fO () else fS (n-1))
                  (fun _ -> [])
                  (fun n0 ->
                  (kv0 "redeliveryPolicy"
                    (obj
                      ((kv0 "maximumRedeliveries"
                         (ntxt0 (Stdlib.Int.succ n0))) :: ((kv0
                                                             "redeliveryDelay"
                                                             (jstr (s0 "0"))) :: [])))) :: [])
                  k.c_redeliveries)
               (app
                 (match k.c_handled with
                  | Some b ->
                    (kv0 "handled"
                      (obj ((kv0 "constant" (jstr (btxt0 b))) :: []))) :: []
                  | None -> [])
                 (app
                   (if k.c_continued
                    then (kv0 "continued"
                           (obj ((kv0 "constant" (jstr (s0 "true"))) :: []))) :: []
                    else [])
                   ((kv0 "steps" (ysteps k.c_steps)) :: [])))))))) :: [])

(** val yeh : ehconf -> chars list **)

let yeh = function
| EHDefault -> []
| EHDlc (q, n0, uo) ->
  (kv0 "errorHandler"
    (obj
      ((kv0 "deadLetterChannel"
         (obj
           (app ((kv0 "deadLetterUri" (jstr (app (s0 "mock:") q))) :: [])
             (app
               (match uo with
                | UONone -> []
                | UOMessage -> (kv0 "useOriginalMessage" (s0 "true")) :: []
                | UOBody -> (kv0 "useOriginalBody" (s0 "true")) :: [])
               ((kv0 "redeliveryPolicy"
                  (obj
                    ((kv0 "maximumRedeliveries" (ntxt0 n0)) :: ((kv0
                                                                  "redeliveryDelay"
                                                                  (jstr
                                                                    (s0 "0"))) :: [])))) :: []))))) :: []))) :: []

(** val yoc : oncomp -> chars **)

let yoc o =
  obj
    ((kv0 "routeConfiguration"
       (obj
         ((kv0 "id" (jstr (s0 "ocConfig"))) :: ((kv0 "onCompletion"
                                                  (arr
                                                    ((obj
                                                       ((kv0 "onCompletion"
                                                          (obj
                                                            (app
                                                              (match o.oc_trig with
                                                               | OcAlways ->
                                                                 []
                                                               | OcComplete ->
                                                                 (kv0
                                                                   "onCompleteOnly"
                                                                   (jstr
                                                                    (s0
                                                                    "true"))) :: []
                                                               | OcFailure ->
                                                                 (kv0
                                                                   "onFailureOnly"
                                                                   (jstr
                                                                    (s0
                                                                    "true"))) :: [])
                                                              (app
                                                                (if o.oc_before
                                                                 then 
                                                                   (kv0 "mode"
                                                                    (jstr
                                                                    (s0
                                                                    "BeforeConsumer"))) :: []
                                                                 else [])
                                                                (app
                                                                  (if o.oc_orig
                                                                   then 
                                                                    (kv0
                                                                    "useOriginalMessage"
                                                                    (jstr
                                                                    (s0
                                                                    "true"))) :: []
                                                                   else [])
                                                                  (app
                                                                    (
                                                                    match o.oc_when with
                                                                    | Some p ->
                                                                    (kv0
                                                                    "onWhen"
                                                                    (obj
                                                                    ((exprf p) :: []))) :: []
                                                                    | None ->
                                                                    [])
                                                                    (
                                                                    (kv0
                                                                    "steps"
                                                                    (ysteps
                                                                    o.oc_steps)) :: []))))))) :: [])) :: []))) :: [])))) :: [])

(** val yroute : ehconf -> bool -> route -> chars **)

let yroute e rc r =
  obj
    ((kv0 "route"
       (obj
         (app ((kv0 "id" (jstr r.r_id)) :: [])
           (app (yeh e)
             (app
               (if rc
                then (kv0 "routeConfigurationId" (jstr (s0 "ocConfig"))) :: []
                else [])
               ((kv0 "from"
                  (obj
                    ((kv0 "uri" (jstr (app (s0 "direct:") r.r_from))) :: (
                    (kv0 "steps" (ysteps r.r_steps)) :: [])))) :: [])))))) :: [])

(** val yaml_program :
    clause list -> ehconf -> oncomp option -> route list -> chars **)

let yaml_program c e oC p =
  arr
    (app (map yclause c)
      (app (match oC with
            | Some o -> (yoc o) :: []
            | None -> [])
        (match p with
         | [] -> []
         | r1 :: rs ->
           (yroute e (match oC with
                      | Some _ -> true
                      | None -> false) r1) :: (map (yroute e false) rs))))
